// Generated by scripts/pieces-source.ts from src/pieces/ and src/sections/ — do not edit by hand.
import type { HeroId, PieceId, SectionId } from '@/types/domain'

export const pieceSource: Record<PieceId, string> = {
  "text-effect": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Effect\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// Reveals a headline word by word (or letter by letter) once it enters the viewport. Colors and fonts come from the recipe tokens.\nimport { motion, useReducedMotion, type Variants } from 'motion/react'\nimport type { JSX } from 'react'\n\ntype Preset = 'blur' | 'slide' | 'fade'\nconst ITEM: Record<Preset, Variants> = {\n  blur: { hidden: { opacity: 0, filter: 'blur(10px)', y: 8 }, visible: { opacity: 1, filter: 'blur(0px)', y: 0 } },\n  slide: { hidden: { opacity: 0, y: '0.6em' }, visible: { opacity: 1, y: 0 } },\n  fade: { hidden: { opacity: 0 }, visible: { opacity: 1 } },\n}\n\nexport function TextEffect({ children, as = 'h2', per = 'word', preset = 'slide', delay = 0, className }: {\n  children: string; as?: keyof JSX.IntrinsicElements; per?: 'word' | 'char'; preset?: Preset; delay?: number; className?: string\n}) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  const parts = per === 'word' ? children.split(/(\\s+)/) : children.split('')\n  return (\n    <Tag className={className} initial=\"hidden\" whileInView=\"visible\" viewport={{ once: true, amount: 0.6 }}\n      transition={reduce ? { duration: 0 } : { staggerChildren: per === 'word' ? 0.06 : 0.025, delayChildren: delay }}> {/* same markup either way (hydration); reduced motion only drops the timing */}\n      <span className=\"sr-only\">{children}</span>\n      {parts.map((p, i) => /^\\s+$/.test(p) ? p /* plain spaces, so a wrapped line never starts indented */ : (\n        <motion.span key={i} aria-hidden className=\"inline-block whitespace-pre\" variants={ITEM[preset]} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: [0.22, 1, 0.36, 1] }}>{p}</motion.span>\n      ))}\n    </Tag>\n  )\n}\n",
  "text-loop": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Loop\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// One word of a headline cycles through a short list (\"We build | shops | archives | tools\").\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function TextLoop({ words, interval = 2.4, className }: { words: string[]; interval?: number; className?: string }) {\n  const [i, setI] = useState(0)\n  const reduce = useReducedMotion()\n  useEffect(() => {\n    if (reduce || words.length < 2) return\n    const t = setInterval(() => setI((x) => (x + 1) % words.length), interval * 1000)\n    return () => clearInterval(t)\n  }, [reduce, words.length, interval])\n  return (\n    <span className={`relative inline-block whitespace-nowrap align-bottom ${className ?? ''}`} aria-live=\"off\">\n      <span className=\"sr-only\">{words.join(', ')}</span>\n      <AnimatePresence mode=\"popLayout\" initial={false}>\n        <motion.span key={i} aria-hidden className=\"inline-block\" initial={{ y: '100%', opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: '-100%', opacity: 0 }} transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}>\n          {words[i]}\n        </motion.span>\n      </AnimatePresence>\n    </span>\n  )\n}\n",
  "split-flap": "'use client'\n// OpusKit piece — based on Componentry \"Split Flap Display\" (MIT © Componentry, https://componentry.dev).\n// Departure-board letters that flick through characters until they land. Dates, times, gate numbers, short words.\nimport { useInView, useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst FLAPS = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-–:./'\n\nexport function SplitFlap({ text, className }: { text: string; className?: string }) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true, amount: 0.8 })\n  const reduce = useReducedMotion()\n  const target = text.toUpperCase()\n  const [shown, setShown] = useState(reduce ? target : target.replace(/\\S/g, ' '))\n  useEffect(() => {\n    if (!inView || reduce) { setShown(target); return }\n    let tick = 0\n    const t = setInterval(() => {\n      tick++\n      setShown(target.split('').map((c, i) => (c === ' ' || tick > 6 + i * 2 ? c : FLAPS[(tick * 7 + i * 3) % FLAPS.length])).join(''))\n      if (tick > 6 + target.length * 2) clearInterval(t)\n    }, 55)\n    return () => clearInterval(t)\n  }, [inView, reduce, target])\n  return (\n    <span ref={ref} className={`inline-flex gap-[0.08em] ${className ?? ''}`} aria-label={text}>\n      {shown.split('').map((c, i) => (\n        <span key={i} aria-hidden className=\"relative inline-grid w-[0.78em] place-items-center overflow-hidden rounded-[0.08em] bg-(--color-text) py-[0.08em] text-(--color-background) tabular-nums\">\n          {c === ' ' ? ' ' : c}\n          <span className=\"absolute inset-x-0 top-1/2 h-px bg-(--color-background)/40\" />\n        </span>\n      ))}\n    </span>\n  )\n}\n",
  "number-ticker": "'use client'\n// OpusKit piece — adapted from Magic UI \"Number Ticker\" (MIT © Magic UI, https://magicui.design).\n// A number that counts up to its value when it scrolls into view. For real figures only — never decoration.\nimport { useInView, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport { useEffect, useRef } from 'react'\n\nexport function NumberTicker({ value, decimals = 0, locale = 'en-US', className }: { value: number; decimals?: number; locale?: string; className?: string }) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true })\n  const reduce = useReducedMotion()\n  const mv = useMotionValue(0)\n  const spring = useSpring(mv, { damping: 60, stiffness: 100 })\n  const fmt = (n: number) => new Intl.NumberFormat(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(n)\n  useEffect(() => { if (inView) mv.set(value) }, [inView, mv, value])\n  useEffect(() => spring.on('change', (v) => { if (ref.current) ref.current.textContent = fmt(v) }), [spring]) // eslint-disable-line react-hooks/exhaustive-deps\n  return <span ref={ref} className={`tabular-nums ${className ?? ''}`}>{fmt(reduce ? value : 0)}</span>\n}\n",
  "text-scramble": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Scramble\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// Letters resolve out of random characters — on first view, and again on hover. Best on short labels and nav links.\nimport { useInView, useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'\n\nexport function TextScramble({ children, duration = 0.8, className, replayOnHover = true }: {\n  children: string; duration?: number; className?: string; replayOnHover?: boolean\n}) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true })\n  const reduce = useReducedMotion()\n  const [text, setText] = useState(children)\n  const timer = useRef<ReturnType<typeof setInterval>>(undefined)\n\n  const run = () => {\n    if (reduce) return\n    clearInterval(timer.current)\n    const steps = Math.max(8, Math.round(duration / 0.04))\n    let step = 0\n    timer.current = setInterval(() => {\n      const shown = (step / steps) * children.length\n      setText(children.split('').map((c, i) => (c === ' ' || i < shown ? c : CHARS[Math.floor(Math.random() * CHARS.length)])).join(''))\n      if (++step > steps) { clearInterval(timer.current); setText(children) }\n    }, 40)\n  }\n  useEffect(() => { if (inView) run() }, [inView]) // eslint-disable-line react-hooks/exhaustive-deps\n  useEffect(() => () => clearInterval(timer.current), [])\n\n  return (\n    <span ref={ref} className={className} onMouseEnter={replayOnHover ? run : undefined}>\n      <span className=\"sr-only\">{children}</span>\n      <span aria-hidden className=\"tabular-nums\">{text}</span>\n    </span>\n  )\n}\n",
  "text-roll": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Roll\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// On hover each letter rolls over to a copy of itself, one after another. For nav links and text buttons.\nimport { motion, useReducedMotion } from 'motion/react'\n\nexport function TextRoll({ children, className }: { children: string; className?: string }) {\n  const reduce = useReducedMotion()\n  const letters = children.split('')\n  return (\n    <motion.span className={`relative inline-flex overflow-hidden ${className ?? ''}`} initial=\"rest\" whileHover={reduce ? undefined : 'hover'} whileFocus={reduce ? undefined : 'hover'} aria-label={children}>\n      {letters.map((l, i) => (\n        <span key={i} aria-hidden className=\"relative inline-block\">\n          <motion.span className=\"inline-block\" variants={{ rest: { y: 0 }, hover: { y: '-100%' } }} transition={{ duration: 0.3, delay: i * 0.02, ease: [0.65, 0, 0.35, 1] }}>{l === ' ' ? ' ' : l}</motion.span>\n          <motion.span className=\"absolute left-0 top-full inline-block\" variants={{ rest: { y: 0 }, hover: { y: '-100%' } }} transition={{ duration: 0.3, delay: i * 0.02, ease: [0.65, 0, 0.35, 1] }}>{l === ' ' ? ' ' : l}</motion.span>\n        </span>\n      ))}\n    </motion.span>\n  )\n}\n",
  "spinning-text": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Spinning Text\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A slowly turning ring of text — a stamp or badge beside a hero, CTA or scroll hint.\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { CSSProperties } from 'react'\n\nexport function SpinningText({ children, radius = 5, duration = 18, className }: { children: string; radius?: number; duration?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const letters = [...children]\n  return (\n    <motion.div className={`relative size-[calc(var(--r)*2ch+2ch)] ${className ?? ''}`} style={{ '--r': radius } as CSSProperties}\n      animate={reduce ? undefined : { rotate: 360 }} transition={{ duration, repeat: Infinity, ease: 'linear' }}>\n      <span className=\"sr-only\">{children}</span>\n      {letters.map((l, i) => (\n        <span key={i} aria-hidden className=\"absolute left-1/2 top-1/2 inline-block\"\n          style={{ transform: `translate(-50%, -50%) rotate(${(360 / letters.length) * i}deg) translateY(calc(var(--r) * -1ch))` }}>{l}</span>\n      ))}\n    </motion.div>\n  )\n}\n",
  "text-reveal": "'use client'\n// OpusKit piece — adapted from Magic UI \"Text Reveal\" (MIT © Magic UI, https://magicui.design).\n// A statement paragraph whose words light up one by one as the visitor scrolls through it.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nfunction Word({ children, progress, range }: { children: string; progress: MotionValue<number>; range: [number, number] }) {\n  const opacity = useTransform(progress, range, [0.18, 1])\n  return <motion.span style={{ opacity }} className=\"mr-[0.25em] inline-block\">{children}</motion.span>\n}\n\nexport function TextReveal({ children, className }: { children: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start 0.8', 'end 0.4'] })\n  const words = children.split(' ')\n  if (reduce) return <p className={className}>{children}</p>\n  return (\n    <div ref={ref}>\n      <p className={`flex flex-wrap ${className ?? ''}`} aria-label={children}>\n        {words.map((w, i) => <Word key={i} progress={scrollYProgress} range={[i / words.length, (i + 1) / words.length]}>{w}</Word>)}\n      </p>\n    </div>\n  )\n}\n",
  "marquee": "'use client'\n// OpusKit piece — adapted from Magic UI \"Marquee\" (MIT © Magic UI, https://magicui.design).\n// An endless row (logos, photos, words). Pauses on hover and off-screen; reduced motion shows a static, scrollable row.\nimport type { CSSProperties, ReactNode } from 'react'\n\nexport function Marquee({ children, reverse = false, seconds = 40, gap = '1.5rem', pauseOnHover = true, className }: {\n  children: ReactNode; reverse?: boolean; seconds?: number; gap?: string; pauseOnHover?: boolean; className?: string\n}) {\n  return (\n    <div className={`group flex overflow-hidden [gap:var(--gap)] motion-reduce:overflow-x-auto ${className ?? ''}`} style={{ '--gap': gap, '--dur': `${seconds}s` } as CSSProperties}>\n      <style>{`@keyframes opuskit-marquee{to{transform:translateX(calc(-100% - var(--gap)))}}`}</style>\n      {[0, 1].map((k) => (\n        <div key={k} aria-hidden={k === 1 || undefined}\n          className={`flex shrink-0 items-center [gap:var(--gap)] [animation:opuskit-marquee_var(--dur)_linear_infinite] motion-reduce:[animation:none] ${reverse ? '[animation-direction:reverse]' : ''} ${pauseOnHover ? 'group-hover:[animation-play-state:paused]' : ''} ${k === 1 ? 'motion-reduce:hidden' : ''}`}>\n          {children}\n        </div>\n      ))}\n    </div>\n  )\n}\n",
  "image-comparison": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Image Comparison\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// Before / after: drag (or use arrow keys on) the divider to compare two photos of the same frame.\nimport { motion, useMotionValue, useTransform } from 'motion/react'\nimport { useRef, useState } from 'react'\n\nexport function ImageComparison({ before, after, beforeAlt, afterAlt, className }: { before: string; after: string; beforeAlt: string; afterAlt: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const pos = useMotionValue(50)\n  const [val, setVal] = useState(50)\n  const clip = useTransform(pos, (v) => `inset(0 ${100 - v}% 0 0)`)\n  const left = useTransform(pos, (v) => `${v}%`)\n  const set = (v: number) => { const c = Math.min(100, Math.max(0, v)); pos.set(c); setVal(Math.round(c)) }\n  const fromPointer = (x: number) => { const r = ref.current!.getBoundingClientRect(); set(((x - r.left) / r.width) * 100) }\n  return (\n    <div ref={ref} className={`relative select-none overflow-hidden touch-pan-y ${className ?? ''}`}\n      onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); fromPointer(e.clientX) }}\n      onPointerMove={(e) => { if (e.buttons) fromPointer(e.clientX) }}>\n      <img src={after} alt={afterAlt} className=\"absolute inset-0 size-full object-cover\" draggable={false} />\n      <motion.img src={before} alt={beforeAlt} className=\"absolute inset-0 size-full object-cover\" style={{ clipPath: clip }} draggable={false} />\n      <motion.div style={{ left }} className=\"absolute inset-y-0 w-px -translate-x-1/2 bg-(--color-background)\">\n        <button type=\"button\" role=\"slider\" aria-label=\"Compare photos\" aria-valuemin={0} aria-valuemax={100} aria-valuenow={val}\n          onKeyDown={(e) => { if (e.key === 'ArrowLeft') set(val - 5); if (e.key === 'ArrowRight') set(val + 5) }}\n          className=\"absolute left-1/2 top-1/2 size-10 -translate-x-1/2 -translate-y-1/2 cursor-ew-resize rounded-full border border-(--color-background) bg-(--color-text)/60 backdrop-blur focus-visible:outline-2 focus-visible:outline-(--color-accent)\" />\n      </motion.div>\n    </div>\n  )\n}\n",
  "ring-carousel": "'use client'\n// OpusKit piece — adapted from Cult UI \"3D Carousel\" (MIT © 2023 Jordan-Gilliam, https://www.cult-ui.com).\n// Photos on the inside of a turning cylinder; drag to spin, click to open one large. Reduced motion: a plain swipe row.\nimport { AnimatePresence, animate, motion, useMotionValue, useReducedMotion, useTransform } from 'motion/react'\nimport { useState } from 'react'\n\nexport type RingPhoto = { src: string; alt: string }\n\nexport function RingCarousel({ photos, height = 420, className }: { photos: RingPhoto[]; height?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const [open, setOpen] = useState<RingPhoto | null>(null)\n  const rotation = useMotionValue(0)\n  const transform = useTransform(rotation, (v) => `rotateY(${v}deg)`)\n  const width = Math.max(1100, photos.length * 180)\n  const face = width / photos.length\n  const radius = width / (2 * Math.PI)\n  if (reduce) return (\n    <div className={`flex snap-x gap-4 overflow-x-auto ${className ?? ''}`}>\n      {photos.map((p) => <img key={p.src} src={p.src} alt={p.alt} className=\"h-72 w-auto shrink-0 snap-center object-cover\" />)}\n    </div>\n  )\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`} style={{ height, perspective: 1000 }}>\n      <motion.div className=\"relative mx-auto h-full touch-pan-y cursor-grab active:cursor-grabbing\" style={{ width, transform, transformStyle: 'preserve-3d' }}\n        onPan={(_, i) => rotation.set(rotation.get() + i.delta.x * 0.1)}\n        onPanEnd={(_, i) => animate(rotation, rotation.get() + i.velocity.x * 0.02, { type: 'spring', stiffness: 100, damping: 30 })}>\n        {photos.map((p, i) => (\n          <button type=\"button\" key={p.src} onClick={() => setOpen(p)} aria-label={`Open: ${p.alt}`}\n            className=\"absolute inset-y-0 left-1/2 flex items-center p-2\" style={{ width: face, marginLeft: -face / 2, transform: `rotateY(${(360 / photos.length) * i}deg) translateZ(${radius}px)` }}>\n            <img src={p.src} alt=\"\" className=\"pointer-events-none aspect-[3/4] w-full object-cover\" draggable={false} />\n          </button>\n        ))}\n      </motion.div>\n      <AnimatePresence>\n        {open && (\n          <motion.button type=\"button\" onClick={() => setOpen(null)} aria-label=\"Close photo\" className=\"fixed inset-0 z-50 grid place-items-center bg-(--color-text)/80 p-6\"\n            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>\n            <motion.img src={open.src} alt={open.alt} className=\"max-h-full max-w-full object-contain\" initial={{ scale: 0.9 }} animate={{ scale: 1 }} />\n          </motion.button>\n        )}\n      </AnimatePresence>\n    </div>\n  )\n}\n",
  "image-field": "'use client'\n// OpusKit piece — based on Componentry \"Infinite Image Field\" (MIT © Componentry, https://componentry.dev).\n// A field of photos visitors drag in any direction, forever: tiles wrap around so the edge never arrives.\nimport { animate, motion, useMotionValue, useReducedMotion, useTransform, type MotionValue } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nexport type FieldPhoto = { src: string; alt: string }\nconst wrap = (v: number, size: number) => ((v % size) + size) % size\n\nfunction Tile({ photo, x, y, ox, oy, cols, rows, cell }: { photo: FieldPhoto; x: MotionValue<number>; y: MotionValue<number>; ox: number; oy: number; cols: number; rows: number; cell: number }) {\n  const tx = useTransform(x, (v) => wrap(ox * cell + v, cols * cell) - cell)\n  const ty = useTransform(y, (v) => wrap(oy * cell + v, rows * cell) - cell)\n  return (\n    <motion.div className=\"absolute left-0 top-0 p-2\" style={{ x: tx, y: ty, width: cell, height: cell }}>\n      <img src={photo.src} alt={photo.alt} className=\"size-full object-cover\" draggable={false} />\n    </motion.div>\n  )\n}\n\nexport function ImageField({ photos, cell = 260, className }: { photos: FieldPhoto[]; cell?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [size, setSize] = useState({ w: 1200, h: 700 })\n  const x = useMotionValue(0), y = useMotionValue(0)\n  useEffect(() => {\n    const el = ref.current; if (!el) return\n    const ro = new ResizeObserver(() => setSize({ w: el.offsetWidth, h: el.offsetHeight }))\n    ro.observe(el); return () => ro.disconnect()\n  }, [])\n  const cols = Math.ceil(size.w / cell) + 2, rows = Math.ceil(size.h / cell) + 2\n  if (reduce) return (\n    <div className={`grid grid-cols-2 gap-3 sm:grid-cols-3 ${className ?? ''}`}>{photos.map((p) => <img key={p.src} src={p.src} alt={p.alt} className=\"aspect-square w-full object-cover\" />)}</div>\n  )\n  return (\n    <motion.div ref={ref} className={`relative touch-none cursor-grab overflow-hidden active:cursor-grabbing ${className ?? ''}`}\n      onPan={(_, i) => { x.set(x.get() + i.delta.x); y.set(y.get() + i.delta.y) }}\n      onPanEnd={(_, i) => { const glide = { duration: 0.9, ease: [0.22, 1, 0.36, 1] as const }; animate(x, x.get() + i.velocity.x * 0.25, glide); animate(y, y.get() + i.velocity.y * 0.25, glide) }}>\n      {Array.from({ length: cols * rows }, (_, k) => {\n        const ox = k % cols, oy = Math.floor(k / cols)\n        return <Tile key={k} photo={photos[(ox + oy * 3) % photos.length]} x={x} y={y} ox={ox} oy={oy} cols={cols} rows={rows} cell={cell} />\n      })}\n      <span className=\"pointer-events-none absolute bottom-4 left-1/2 -translate-x-1/2 bg-(--color-background) px-3 py-1 text-sm text-(--color-text)\">Drag to explore</span>\n    </motion.div>\n  )\n}\n",
  "tilted-grid": "'use client'\n// OpusKit piece — based on Componentry \"Scroll Tilted Grid\" (MIT © Componentry, https://componentry.dev).\n// A dense photo grid laid back in perspective that stands up flat as the visitor scrolls into it.\nimport { motion, useReducedMotion, useScroll, useTransform } from 'motion/react'\nimport { useRef } from 'react'\n\nexport function TiltedGrid({ photos, columns = 5, className }: { photos: { src: string; alt: string }[]; columns?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'center center'] })\n  const rotateX = useTransform(scrollYProgress, [0, 1], [45, 0])\n  const scale = useTransform(scrollYProgress, [0, 1], [0.8, 1])\n  const lift = useTransform(scrollYProgress, [0, 1], [80, 0])\n  return (\n    <div ref={ref} className={`overflow-hidden [perspective:1200px] ${className ?? ''}`}>\n      <motion.div className=\"grid gap-3\" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`, ...(reduce ? {} : { rotateX, scale, transformOrigin: '50% 0%' }) }}>\n        {photos.map((p, i) => (\n          <motion.img key={p.src + i} src={p.src} alt={p.alt} className=\"aspect-[3/4] w-full object-cover\" style={reduce || i % 2 === 0 ? undefined : { y: lift }} />\n        ))}\n      </motion.div>\n    </div>\n  )\n}\n",
  "image-trail": "'use client'\n// OpusKit piece — based on Animata \"Trailing Image\" (MIT © Animata, https://animata.design).\n// Moving the cursor across the section leaves a short trail of photos that fade away. Fine pointers only.\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { useRef, useState, type ReactNode } from 'react'\n\ntype Drop = { id: number; x: number; y: number; src: string }\n\nexport function ImageTrail({ photos, children, spacing = 90, className }: { photos: string[]; children?: ReactNode; spacing?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const [drops, setDrops] = useState<Drop[]>([])\n  const last = useRef({ x: 0, y: 0, n: 0 })\n  const onMove = (e: React.PointerEvent<HTMLDivElement>) => {\n    if (reduce || e.pointerType !== 'mouse') return\n    const r = e.currentTarget.getBoundingClientRect()\n    const x = e.clientX - r.left, y = e.clientY - r.top\n    if (Math.hypot(x - last.current.x, y - last.current.y) < spacing) return\n    const n = ++last.current.n\n    last.current.x = x; last.current.y = y\n    setDrops((d) => [...d.slice(-6), { id: n, x, y, src: photos[n % photos.length] }])\n    setTimeout(() => setDrops((d) => d.filter((z) => z.id !== n)), 900)\n  }\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`} onPointerMove={onMove}>\n      <AnimatePresence>\n        {drops.map((d) => (\n          <motion.img key={d.id} src={d.src} alt=\"\" aria-hidden className=\"pointer-events-none absolute z-0 w-40 -translate-x-1/2 -translate-y-1/2 object-cover\"\n            style={{ left: d.x, top: d.y }} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }} transition={{ duration: 0.35 }} />\n        ))}\n      </AnimatePresence>\n      <div className=\"relative z-10\">{children}</div>\n    </div>\n  )\n}\n",
  "tilt": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Tilt\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A card that leans toward the cursor in 3D. Keep the angle small (≤ 8°) so it reads as craft, not a gimmick.\nimport { motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport function Tilt({ children, degrees = 8, className }: { children: ReactNode; degrees?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const x = useSpring(useMotionValue(0), { stiffness: 200, damping: 20 })\n  const y = useSpring(useMotionValue(0), { stiffness: 200, damping: 20 })\n  const rx = useTransform(y, [-0.5, 0.5], [degrees, -degrees])\n  const ry = useTransform(x, [-0.5, 0.5], [-degrees, degrees])\n  const transform = useMotionTemplate`perspective(900px) rotateX(${rx}deg) rotateY(${ry}deg)`\n  if (reduce) return <div className={className}>{children}</div>\n  return (\n    <motion.div className={className} style={{ transform, transformStyle: 'preserve-3d' }}\n      onPointerMove={(e) => { if (e.pointerType !== 'mouse') return; const r = e.currentTarget.getBoundingClientRect(); x.set((e.clientX - r.left) / r.width - 0.5); y.set((e.clientY - r.top) / r.height - 0.5) }}\n      onPointerLeave={() => { x.set(0); y.set(0) }}>\n      {children}\n    </motion.div>\n  )\n}\n",
  "cursor-area": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Cursor\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A custom cursor inside one area (a gallery, a hero) — e.g. a round \"View\" label over project photos.\n// Only on fine pointers; the system cursor stays everywhere else.\nimport { AnimatePresence, motion, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport { useState, type ReactNode } from 'react'\n\nexport function CursorArea({ children, label = 'View', className }: { children: ReactNode; label?: string; className?: string }) {\n  const reduce = useReducedMotion()\n  const [on, setOn] = useState(false)\n  const x = useSpring(useMotionValue(0), { stiffness: 500, damping: 40 })\n  const y = useSpring(useMotionValue(0), { stiffness: 500, damping: 40 })\n  return (\n    <div className={`relative ${on ? 'cursor-none' : ''} ${className ?? ''}`}\n      onPointerEnter={(e) => !reduce && e.pointerType === 'mouse' && setOn(true)} onPointerLeave={() => setOn(false)}\n      onPointerMove={(e) => { const r = e.currentTarget.getBoundingClientRect(); x.set(e.clientX - r.left); y.set(e.clientY - r.top) }}>\n      {children}\n      <AnimatePresence>\n        {on && (\n          <motion.span aria-hidden className=\"pointer-events-none absolute left-0 top-0 z-20 grid size-20 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-(--color-accent) text-sm text-(--color-background)\"\n            style={{ x, y }} initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }} transition={{ duration: 0.2 }}>{label}</motion.span>\n        )}\n      </AnimatePresence>\n    </div>\n  )\n}\n",
  "magnetic": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Magnetic\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A button or link that leans toward the cursor when it comes near. Use on one or two primary actions only.\nimport { motion, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport function Magnetic({ children, strength = 0.35, className }: { children: ReactNode; strength?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const x = useSpring(useMotionValue(0), { stiffness: 150, damping: 12, mass: 0.2 })\n  const y = useSpring(useMotionValue(0), { stiffness: 150, damping: 12, mass: 0.2 })\n  return (\n    <motion.span className={`inline-block ${className ?? ''}`} style={{ x, y }}\n      onPointerMove={(e) => { if (reduce || e.pointerType !== 'mouse') return; // reduced motion: stays put (same markup, so hydration matches)\n      const r = e.currentTarget.getBoundingClientRect(); x.set((e.clientX - r.left - r.width / 2) * strength); y.set((e.clientY - r.top - r.height / 2) * strength) }}\n      onPointerLeave={() => { x.set(0); y.set(0) }}>\n      {children}\n    </motion.span>\n  )\n}\n",
  "hover-highlight": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Animated Background\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// One highlight slides between items as the pointer (or focus) moves — nav links, filters, tabs, a list of names.\nimport { motion } from 'motion/react'\nimport { useId, useState, type ElementType } from 'react'\n\nexport function HoverHighlight({ link: L = 'a', items, className, itemClassName }: { link?: ElementType; items: { label: string; href: string }[]; className?: string; itemClassName?: string }) {\n  const [active, setActive] = useState<string | null>(null)\n  const id = useId()\n  return (\n    <ul className={`flex ${className ?? ''}`} onPointerLeave={() => setActive(null)}>\n      {items.map((it) => (\n        <li key={it.href} className=\"relative\">\n          {active === it.href && <motion.span layoutId={id} className=\"absolute inset-0 bg-(--color-surface)\" transition={{ type: 'spring', bounce: 0.15, duration: 0.35 }} />}\n          <L href={it.href} className={`relative block px-3 py-2 ${itemClassName ?? ''}`} onPointerEnter={() => setActive(it.href)} onFocus={() => setActive(it.href)} onBlur={() => setActive(null)}>{it.label}</L>\n        </li>\n      ))}\n    </ul>\n  )\n}\n",
  "scroll-progress": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Scroll Progress\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A hairline across the top that fills as the visitor reads. For long pages: journal posts, case studies, FAQs.\nimport { motion, useScroll, useSpring } from 'motion/react'\n\nexport function ScrollProgress({ className }: { className?: string }) {\n  const { scrollYProgress } = useScroll()\n  const scaleX = useSpring(scrollYProgress, { stiffness: 200, damping: 50, restDelta: 0.001 })\n  return <motion.div aria-hidden className={`fixed inset-x-0 top-0 z-50 h-0.5 origin-left bg-(--color-accent) ${className ?? ''}`} style={{ scaleX }} />\n}\n",
  "velocity-band": "'use client'\n// OpusKit piece — adapted from Magic UI \"Scroll Based Velocity\" (MIT © Magic UI, https://magicui.design).\n// A band of big type that drifts sideways and speeds up (or reverses) with the visitor's scroll.\nimport { motion, useAnimationFrame, useMotionValue, useReducedMotion, useScroll, useSpring, useTransform, useVelocity } from 'motion/react'\nimport { useRef } from 'react'\n\nconst wrap = (min: number, max: number, v: number) => ((((v - min) % (max - min)) + (max - min)) % (max - min)) + min\n\nexport function VelocityBand({ text, speed = 3, className }: { text: string; speed?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const base = useMotionValue(0)\n  const { scrollY } = useScroll()\n  const velocity = useSpring(useVelocity(scrollY), { damping: 50, stiffness: 400 })\n  const factor = useTransform(velocity, [0, 1000], [0, 5], { clamp: false })\n  const x = useTransform(base, (v) => `${wrap(-50, -25, v)}%`)\n  const dir = useRef(1)\n  useAnimationFrame((_, delta) => {\n    if (reduce) return\n    const f = factor.get()\n    if (f < 0) dir.current = -1; else if (f > 0) dir.current = 1\n    base.set(base.get() + dir.current * speed * (delta / 1000) * (1 + Math.abs(f)))\n  })\n  return (\n    <div className={`overflow-hidden whitespace-nowrap ${className ?? ''}`} aria-label={text}>\n      <motion.div aria-hidden className=\"flex w-max\" style={reduce ? undefined : { x }}>\n        {[0, 1, 2, 3].map((k) => <span key={k} className=\"pr-[0.5em]\">{text}</span>)}\n      </motion.div>\n    </div>\n  )\n}\n",
  "sticky-cards": "'use client'\n// OpusKit piece — based on Componentry \"Sticky Scroll Cards\" (MIT © Componentry, https://componentry.dev).\n// Cards stack on top of each other while scrolling; each one settles and shrinks slightly as the next arrives.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef, type ReactNode } from 'react'\n\nfunction Card({ children, i, total, progress }: { children: ReactNode; i: number; total: number; progress: MotionValue<number> }) {\n  const scale = useTransform(progress, [i / total, 1], [1, 1 - (total - i) * 0.04])\n  return (\n    <div className=\"sticky flex h-[85svh] items-start justify-center\" style={{ top: `calc(8svh + ${i * 1.5}rem)` }}>\n      <motion.div className=\"h-[70svh] w-full origin-top overflow-hidden bg-(--color-surface)\" style={{ scale }}>{children}</motion.div>\n    </div>\n  )\n}\n\nexport function StickyCards({ cards, className }: { cards: ReactNode[]; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] })\n  if (reduce) return <div className={`grid gap-6 ${className ?? ''}`}>{cards.map((c, i) => <div key={i} className=\"bg-(--color-surface)\">{c}</div>)}</div>\n  return <div ref={ref} className={className}>{cards.map((c, i) => <Card key={i} i={i} total={cards.length} progress={scrollYProgress}>{c}</Card>)}</div>\n}\n",
  "grid-pattern": "// OpusKit piece — adapted from Magic UI \"Grid Pattern\" (MIT © Magic UI, https://magicui.design).\n// Hairline grid behind a section, drawn in the border token; optional filled cells mark real positions (a seat map, a schedule).\nimport { useId } from 'react'\n\nexport function GridPattern({ size = 48, cells = [], fade = true, className }: { size?: number; cells?: [number, number][]; fade?: boolean; className?: string }) {\n  const id = useId()\n  return (\n    <svg aria-hidden className={`pointer-events-none absolute inset-0 size-full stroke-(--color-border) ${className ?? ''}`}\n      style={fade ? { maskImage: 'radial-gradient(ellipse at center, black 40%, transparent 80%)' } : undefined}>\n      <defs>\n        <pattern id={id} width={size} height={size} patternUnits=\"userSpaceOnUse\" x={-1} y={-1}>\n          <path d={`M.5 ${size}V.5H${size}`} fill=\"none\" />\n        </pattern>\n      </defs>\n      <rect width=\"100%\" height=\"100%\" strokeWidth={0} fill={`url(#${id})`} />\n      {cells.map(([x, y]) => <rect key={`${x}-${y}`} className=\"fill-(--color-accent)/15\" strokeWidth={0} width={size - 1} height={size - 1} x={x * size} y={y * size} />)}\n    </svg>\n  )\n}\n",
  "grain": "// OpusKit piece — adapted from Magic UI \"Noise Texture\" (MIT © Magic UI, https://magicui.design).\n// Film grain over a section or the whole page, generated in SVG (no image file). Keep it at ≤ 4–8% so it is felt, not seen.\nimport { useId } from 'react'\n\nexport function Grain({ opacity = 0.06, frequency = 0.75, fixed = false, className }: { opacity?: number; frequency?: number; fixed?: boolean; className?: string }) {\n  const id = useId()\n  return (\n    <svg aria-hidden className={`pointer-events-none inset-0 z-40 size-full select-none mix-blend-multiply ${fixed ? 'fixed' : 'absolute'} ${className ?? ''}`} style={{ opacity }}>\n      <filter id={id}>\n        <feTurbulence type=\"fractalNoise\" baseFrequency={frequency} numOctaves={3} stitchTiles=\"stitch\" />\n        <feColorMatrix type=\"saturate\" values=\"0\" />\n      </filter>\n      <rect width=\"100%\" height=\"100%\" filter={`url(#${id})`} />\n    </svg>\n  )\n}\n",
  "magnet-lines": "'use client'\n// OpusKit piece — adapted from Componentry \"Magnet Lines\" (MIT © Componentry, https://componentry.dev).\n// A grid of short lines that all turn to point at the cursor, like iron filings. A quiet, graphic hero or footer field.\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef } from 'react'\n\nexport function MagnetLines({ rows = 9, columns = 12, className }: { rows?: number; columns?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  useEffect(() => {\n    const el = ref.current\n    if (!el || reduce) return\n    const lines = [...el.children] as HTMLElement[]\n    let frame = 0\n    const move = (e: PointerEvent) => {\n      cancelAnimationFrame(frame)\n      frame = requestAnimationFrame(() => {\n        for (const l of lines) {\n          const r = l.getBoundingClientRect()\n          const a = Math.atan2(e.clientY - (r.top + r.height / 2), e.clientX - (r.left + r.width / 2))\n          l.style.transform = `rotate(${a + Math.PI / 2}rad)`\n        }\n      })\n    }\n    window.addEventListener('pointermove', move, { passive: true })\n    return () => { window.removeEventListener('pointermove', move); cancelAnimationFrame(frame) }\n  }, [reduce])\n  return (\n    <div ref={ref} aria-hidden className={`grid place-items-center ${className ?? ''}`} style={{ gridTemplateColumns: `repeat(${columns}, 1fr)`, gridTemplateRows: `repeat(${rows}, 1fr)` }}>\n      {Array.from({ length: rows * columns }, (_, i) => <span key={i} className=\"block h-[3vmin] w-px bg-(--color-text) transition-transform duration-300 ease-out\" />)}\n    </div>\n  )\n}\n",
  "video-dialog": "'use client'\n// OpusKit piece — adapted from Magic UI \"Hero Video Dialog\" (MIT © Magic UI, https://magicui.design).\n// A still (the poster) with a play button; clicking opens the full film with sound in a dialog. Esc or the backdrop closes it.\nimport { AnimatePresence, motion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function VideoDialog({ poster, src, title, className }: { poster: string; src: string; title: string; className?: string }) {\n  const [open, setOpen] = useState(false)\n  useEffect(() => {\n    if (!open) return\n    const esc = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false)\n    window.addEventListener('keydown', esc)\n    return () => window.removeEventListener('keydown', esc)\n  }, [open])\n  return (\n    <>\n      <button type=\"button\" onClick={() => setOpen(true)} className={`group relative block overflow-hidden ${className ?? ''}`} aria-label={`Play: ${title}`}>\n        <img src={poster} alt=\"\" className=\"size-full object-cover transition-transform duration-500 group-hover:scale-[1.02]\" />\n        <span className=\"absolute left-1/2 top-1/2 grid size-20 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-(--color-background) text-(--color-text) transition-transform group-hover:scale-110\">\n          <svg viewBox=\"0 0 24 24\" className=\"ml-1 size-7 fill-current\" aria-hidden><path d=\"M7 4.5v15l13-7.5z\" /></svg>\n        </span>\n      </button>\n      <AnimatePresence>\n        {open && (\n          <motion.div role=\"dialog\" aria-modal=\"true\" aria-label={title} className=\"fixed inset-0 z-50 grid place-items-center bg-(--color-text)/85 p-4 md:p-12\"\n            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setOpen(false)}>\n            <motion.video src={src} poster={poster} controls autoPlay playsInline className=\"max-h-full w-full max-w-6xl bg-black\" onClick={(e) => e.stopPropagation()}\n              initial={{ scale: 0.94, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.94, y: 20 }} transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }} />\n            <button type=\"button\" className=\"absolute right-4 top-4 px-3 py-2 text-(--color-background)\" onClick={() => setOpen(false)}>Close</button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </>\n  )\n}\n",
  "media-between-text": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Media Between Text\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A headline split in two; when it scrolls into view the words part and a photo (or clip) opens between them.\nimport { motion, useInView, useReducedMotion } from 'motion/react'\nimport { useRef } from 'react'\n\nexport function MediaBetweenText({ before, after, src, alt, video = false, width = '18vw', className }: {\n  before: string; after: string; src: string; alt: string; video?: boolean; width?: string; className?: string\n}) {\n  const ref = useRef<HTMLHeadingElement>(null)\n  const inView = useInView(ref, { once: true, amount: 0.7 })\n  const reduce = useReducedMotion()\n  const open = reduce || inView\n  return (\n    <h2 ref={ref} className={`flex flex-wrap items-center justify-center gap-x-[0.2em] ${className ?? ''}`}>\n      <span>{before}</span>\n      <motion.span className=\"inline-block overflow-hidden align-middle\" initial={false} animate={{ width: open ? width : 0, opacity: open ? 1 : 0 }} transition={{ duration: 0.9, ease: [0.65, 0, 0.35, 1] }} style={{ height: '0.85em' }}>\n        {video ? <video src={src} autoPlay muted loop playsInline className=\"size-full object-cover\" aria-label={alt} />\n          : <img src={src} alt={alt} className=\"size-full object-cover\" />}\n      </motion.span>\n      <span>{after}</span>\n    </h2>\n  )\n}\n",
  "cut-reveal": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Vertical Cut Reveal\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Each word (or letter) slides up out of a hard mask, as if cut from the line — sharper than a fade.\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { JSX } from 'react'\n\nexport function CutReveal({ children, as = 'h2', per = 'word', delay = 0, className }: { children: string; as?: keyof JSX.IntrinsicElements; per?: 'word' | 'char'; delay?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  const words = children.split(' ')\n  let n = 0\n  return (\n    <Tag className={className} initial=\"hidden\" whileInView=\"shown\" viewport={{ once: true, amount: 0.6 }}>\n      <span className=\"sr-only\">{children}</span>\n      {words.map((w, wi) => (\n        <span key={wi} aria-hidden className=\"inline-flex overflow-hidden pb-[0.08em] align-bottom\">\n          {(per === 'word' ? [w] : [...w]).map((part, pi) => (\n            <motion.span key={pi} className=\"inline-block\" variants={{ hidden: { y: '105%' }, shown: { y: 0 } }}\n              transition={reduce ? { duration: 0 } : { type: 'spring', stiffness: 190, damping: 22, delay: delay + (n++) * (per === 'word' ? 0.07 : 0.025) }}>{part}</motion.span>\n          ))}\n          {wi < words.length - 1 && <span>&nbsp;</span>}\n        </span>\n      ))}\n    </Tag>\n  )\n}\n",
  "underline-fill": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Underline To Background\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A link whose underline grows into a full background block on hover or focus, flipping the text colour.\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport function UnderlineFill({ href, children, className }: { href: string; children: ReactNode; className?: string }) {\n  const reduce = useReducedMotion()\n  return (\n    <motion.a href={href} className={`relative inline-block px-[0.1em] ${className ?? ''}`} initial=\"rest\" whileHover=\"hover\" whileFocus=\"hover\">\n      <motion.span aria-hidden className=\"absolute inset-x-0 bottom-0 -z-0 bg-(--color-text)\" variants={{ rest: { height: '0.08em' }, hover: { height: reduce ? '0.08em' : '100%' } }} transition={{ duration: 0.25, ease: [0.65, 0, 0.35, 1] }} />\n      <motion.span className=\"relative\" variants={{ rest: { color: 'var(--color-text)' }, hover: { color: reduce ? 'var(--color-text)' : 'var(--color-background)' } }} transition={{ duration: 0.2 }}>{children}</motion.span>\n    </motion.a>\n  )\n}\n",
  "parallax-floating": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Parallax Floating\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Photos scattered around a headline drift against the cursor at different depths, like objects in a vitrine.\nimport { motion, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport type FloatingPhoto = { src: string; alt: string; x: string; y: string; w: string; depth: number }\n\nfunction Floater({ p, mx, my }: { p: FloatingPhoto; mx: MotionValue<number>; my: MotionValue<number> }) {\n  const x = useTransform(mx, (v) => v * p.depth * -30)\n  const y = useTransform(my, (v) => v * p.depth * -30)\n  return <motion.img src={p.src} alt={p.alt} className=\"absolute object-cover\" style={{ left: p.x, top: p.y, width: p.w, x, y }} />\n}\n\nexport function ParallaxFloating({ photos, children, className }: { photos: FloatingPhoto[]; children?: ReactNode; className?: string }) {\n  const reduce = useReducedMotion()\n  const mx = useSpring(useMotionValue(0), { stiffness: 60, damping: 20 })\n  const my = useSpring(useMotionValue(0), { stiffness: 60, damping: 20 })\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`}\n      onPointerMove={(e) => { if (reduce || e.pointerType !== 'mouse') return; const r = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - r.left) / r.width - 0.5); my.set((e.clientY - r.top) / r.height - 0.5) }}\n      onPointerLeave={() => { mx.set(0); my.set(0) }}>\n      {photos.map((p) => <Floater key={p.src + p.x} p={p} mx={mx} my={my} />)}\n      <div className=\"relative z-10 grid size-full place-items-center\">{children}</div>\n    </div>\n  )\n}\n",
  "drag-photos": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Drag Elements\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Photos scattered like prints on a desk; visitors pick one up and drag it around, the last one lands on top.\nimport { motion } from 'motion/react'\nimport { useRef, useState } from 'react'\n\nexport type DeskPhoto = { src: string; alt: string; x: string; y: string; w: string; rotate: number }\n\nexport function DragPhotos({ photos, className }: { photos: DeskPhoto[]; className?: string }) {\n  const area = useRef<HTMLDivElement>(null)\n  const [order, setOrder] = useState(photos.map((_, i) => i))\n  const front = (i: number) => setOrder((o) => [...o.filter((x) => x !== i), i])\n  return (\n    <div ref={area} className={`relative overflow-hidden ${className ?? ''}`}>\n      {photos.map((p, i) => (\n        <motion.img key={p.src + i} src={p.src} alt={p.alt} draggable={false} drag dragConstraints={area} dragElastic={0.2}\n          onPointerDown={() => front(i)} whileDrag={{ scale: 1.04, rotate: 0 }}\n          className=\"absolute cursor-grab touch-none bg-(--color-surface) object-cover p-[0.6%] shadow-[0_10px_30px_rgb(0_0_0/0.18)] active:cursor-grabbing\"\n          style={{ left: p.x, top: p.y, width: p.w, rotate: p.rotate, zIndex: order.indexOf(i) }} />\n      ))}\n    </div>\n  )\n}\n",
  "text-along-path": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Text Along Path\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A line of text that runs along a curve and travels along it as the visitor scrolls.\nimport { motion, useReducedMotion, useScroll, useTransform } from 'motion/react'\nimport { useId, useRef } from 'react'\n\nexport function TextAlongPath({ text, path = 'M0,80 C200,0 400,160 600,80 S1000,0 1200,80', className }: { text: string; path?: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const id = useId()\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] })\n  const offset = useTransform(scrollYProgress, [0, 1], ['0%', '-60%'])\n  return (\n    <div ref={ref} className={className}>\n    <svg viewBox=\"0 0 1200 160\" className=\"w-full overflow-visible fill-(--color-text)\" role=\"img\" aria-label={text}>\n      <path id={id} d={path} fill=\"none\" />\n      <text aria-hidden>\n        <motion.textPath href={`#${id}`} startOffset={reduce ? '0%' : offset}>{`${text} ${text} ${text}`}</motion.textPath>\n      </text>\n    </svg>\n    </div>\n  )\n}\n",
  "shader-grain": "'use client'\n// OpusKit piece — uses Paper Shaders \"Grain Gradient\" (Apache-2.0 © Paper Design, https://shaders.paper.design).\n// A slow, grainy colour field drawn on the GPU from the recipe's own colours — a living background with the texture of print.\nimport { GrainGradient } from '@paper-design/shaders-react'\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst read = (el: Element, v: string) => getComputedStyle(el).getPropertyValue(v).trim()\n\nexport function ShaderGrain({ shape = 'wave', className }: { shape?: 'wave' | 'dots' | 'truchet' | 'corners' | 'ripple' | 'blob'; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [c, setC] = useState<{ back: string; colors: string[] } | null>(null)\n  useEffect(() => { const el = ref.current; if (el) setC({ back: read(el, '--color-background'), colors: [read(el, '--color-accent'), read(el, '--color-surface'), read(el, '--color-text')] }) }, [])\n  return (\n    <div ref={ref} aria-hidden className={`pointer-events-none absolute inset-0 ${className ?? ''}`}>\n      {c && <GrainGradient style={{ width: '100%', height: '100%' }} colorBack={c.back} colors={c.colors} softness={0.7} intensity={0.25} noise={0.35} shape={shape} speed={reduce ? 0 : 0.4} />}\n    </div>\n  )\n}\n",
  "shader-dither": "'use client'\n// OpusKit piece — uses Paper Shaders \"Dithering\" (Apache-2.0 © Paper Design, https://shaders.paper.design).\n// A 1-bit dithered pattern in two recipe colours, like an old screen or a risograph — graphic, never glossy.\nimport { Dithering } from '@paper-design/shaders-react'\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst read = (el: Element, v: string) => getComputedStyle(el).getPropertyValue(v).trim()\n\nexport function ShaderDither({ shape = 'warp', size = 3, className }: { shape?: 'simplex' | 'warp' | 'dots' | 'wave' | 'ripple' | 'swirl' | 'sphere'; size?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [c, setC] = useState<{ back: string; front: string } | null>(null)\n  useEffect(() => { const el = ref.current; if (el) setC({ back: read(el, '--color-background'), front: read(el, '--color-accent') }) }, [])\n  return (\n    <div ref={ref} aria-hidden className={`pointer-events-none absolute inset-0 ${className ?? ''}`}>\n      {c && <Dithering style={{ width: '100%', height: '100%' }} colorBack={c.back} colorFront={c.front} shape={shape} type=\"4x4\" size={size} speed={reduce ? 0 : 0.3} />}\n    </div>\n  )\n}\n",
  "duo-headline": "'use client'\n// OpusKit piece — two-voice headline: one whole word (or phrase) in the loud display face, the rest in the quiet\n// heading face at the same size; letters rise out of a line mask when it comes into view. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { JSX } from 'react'\n\nfunction Letters({ text, from }: { text: string; from: number }) {\n  return <>{[...text].map((ch, i) => (\n    <span key={i} className=\"inline-block overflow-hidden pb-[0.06em] align-bottom\">\n      <motion.span className=\"inline-block\" variants={{ hidden: { y: '110%' }, shown: { y: 0 } }} transition={{ type: 'spring', stiffness: 200, damping: 24, delay: (from + i) * 0.025 }}>{ch === ' ' ? ' ' : ch}</motion.span>\n    </span>\n  ))}</>\n}\n\nexport function DuoHeadline({ loud, quiet, as = 'h2', className }: { loud: string; quiet: string; as?: keyof JSX.IntrinsicElements; className?: string }) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  return (\n    <Tag className={`type-display flex flex-wrap items-baseline justify-center gap-x-[0.25em] ${className ?? ''}`} initial={reduce ? false : 'hidden'} whileInView=\"shown\" viewport={{ once: true, amount: 0.6 }} aria-label={`${loud} ${quiet}`}>\n      <span aria-hidden><Letters text={loud} from={0} /></span>\n      <span aria-hidden className=\"font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\"><Letters text={quiet} from={loud.length} /></span>\n    </Tag>\n  )\n}\n",
  "scribble-link": "'use client'\n// OpusKit piece — a link with a hand-drawn squiggle that draws itself underneath on hover or focus; the current\n// page keeps its squiggle. For navigation. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType, type ReactNode } from 'react'\n\nconst SQUIGGLE = 'M2 7 C 12 3, 22 10, 34 6 S 58 2, 70 6 S 92 11, 98 5'\n\nexport function ScribbleLink({ link: L = 'a', href, children, current = false, className }: { link?: ElementType; href: string; children: ReactNode; current?: boolean; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const drawn = current || on\n  return (\n    <L href={href} aria-current={current ? 'page' : undefined} className={`relative inline-block pb-2 ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      {children}\n      <svg aria-hidden viewBox=\"0 0 100 12\" preserveAspectRatio=\"none\" className=\"absolute inset-x-0 bottom-0 h-2 w-full overflow-visible text-(--color-chapter-1,var(--color-accent))\">\n        <motion.path d={SQUIGGLE} fill=\"none\" stroke=\"currentColor\" strokeWidth={2.2} strokeLinecap=\"round\" vectorEffect=\"non-scaling-stroke\"\n          initial={false} animate={{ pathLength: drawn ? 1 : 0, opacity: drawn ? 1 : 0 }} transition={{ duration: reduce ? 0 : 0.45, ease: [0.65, 0, 0.35, 1] }} />\n      </svg>\n    </L>\n  )\n}\n",
  "wavy-link": "'use client'\n// OpusKit piece — a text link whose underline draws in as a wave on hover or focus. Footer and inline links.\n// Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType, type ReactNode } from 'react'\n\nconst WAVE = 'M0 5 Q 5 0 10 5 T 20 5 T 30 5 T 40 5 T 50 5 T 60 5 T 70 5 T 80 5 T 90 5 T 100 5'\n\nexport function WavyLink({ link: L = 'a', href, children, current = false, className }: { link?: ElementType; href: string; children: ReactNode; current?: boolean; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  return (\n    <L href={href} aria-current={current ? 'page' : undefined} className={`relative inline-block pb-1.5 ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      {children}\n      <svg aria-hidden viewBox=\"0 0 100 10\" preserveAspectRatio=\"none\" className=\"absolute inset-x-0 bottom-0 h-1.5 w-full text-(--color-chapter-2,var(--color-accent))\">\n        <motion.path d={WAVE} fill=\"none\" stroke=\"currentColor\" strokeWidth={1.6} vectorEffect=\"non-scaling-stroke\" initial={false}\n          animate={{ pathLength: on || current ? 1 : 0 }} transition={{ duration: reduce ? 0 : 0.35 }} />\n      </svg>\n    </L>\n  )\n}\n",
  "swap-button": "'use client'\n// OpusKit piece — a playful button: on hover the arrow box hops from the left to the right of the label and the\n// whole button tilts a little, like a sticker being peeled. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState } from 'react'\n\nconst Arrow = () => <svg viewBox=\"0 0 16 16\" className=\"size-4\" aria-hidden><path d=\"M2 8h11M9 4l4 4-4 4\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" /></svg>\n\nexport function SwapButton({ href, label, className }: { href: string; label: string; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const box = <motion.span layout={!reduce} className=\"grid size-11 place-items-center bg-(--color-chapter-2,var(--color-accent)) text-(--color-text)\"><Arrow /></motion.span>\n  return (\n    <motion.a href={href} className={`type-utility inline-flex items-stretch gap-1 [font-family:var(--font-body)] ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}\n      animate={{ rotate: on && !reduce ? -3 : 0 }} transition={{ type: 'spring', stiffness: 300, damping: 18 }}>\n      {!on && box}\n      <motion.span layout={!reduce} className=\"flex items-center bg-(--color-chapter-2,var(--color-accent)) px-4 font-semibold uppercase tracking-tight text-(--color-text)\">{label}</motion.span>\n      {on && box}\n    </motion.a>\n  )\n}\n",
  "stickers": "'use client'\n// OpusKit piece — brand stickers stuck onto a section: each sits at its own angle, drifts with scroll at its own depth,\n// and can be picked up and thrown (it slides to a stop). Put it inside a `relative` section. Original OpusKit code (MIT).\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nexport type Sticker = { src: string; alt: string; x: string; y: string; w: string; rotate: number; depth?: number }\n\nfunction One({ s, progress, reduce }: { s: Sticker; progress: MotionValue<number>; reduce: boolean }) {\n  const y = useTransform(progress, [0, 1], [0, reduce ? 0 : -(s.depth ?? 1) * 120])\n  return (\n    <motion.div className=\"absolute\" style={{ left: s.x, top: s.y, width: s.w, y }}>\n      <motion.img src={s.src} alt={s.alt} draggable={false} drag={!reduce} dragMomentum dragTransition={{ power: 0.25, timeConstant: 220 }}\n        whileDrag={{ scale: 1.08, rotate: s.rotate + 4 }} whileHover={reduce ? undefined : { scale: 1.04 }} style={{ rotate: s.rotate }}\n        className=\"pointer-events-auto w-full cursor-grab touch-none select-none active:cursor-grabbing\" />\n    </motion.div>\n  )\n}\n\nexport function Stickers({ stickers, className }: { stickers: Sticker[]; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = !!useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] })\n  return <div ref={ref} className={`pointer-events-none absolute inset-0 z-20 ${className ?? ''}`}>{stickers.map((s) => <One key={s.src + s.x} s={s} progress={scrollYProgress} reduce={reduce} />)}</div>\n}\n",
  "blob-transition": "'use client'\n// OpusKit piece — page transition: clicking an internal link sends an organic blob of colour up over the page; the\n// next page is revealed as the blob keeps travelling off the top. Mount once in the root layout. Respects reduced\n// motion (plain navigation). Original OpusKit code (MIT).\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { usePathname } from 'next/navigation'\nimport { useEffect, useState } from 'react'\n\nexport function BlobTransition({ color = 'var(--color-chapter-1, var(--color-accent))' }: { color?: string }) {\n  const path = usePathname()\n  const reduce = useReducedMotion()\n  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle')\n  useEffect(() => {\n    if (reduce) return\n    let replaying = false\n    const onClick = (e: MouseEvent) => {\n      if (replaying) return\n      const a = (e.target as HTMLElement).closest('a')\n      if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || a.target === '_blank' || a.hasAttribute('download')) return\n      const url = new URL(a.href, location.href)\n      if (url.origin !== location.origin || (url.pathname === location.pathname && url.hash)) return\n      e.preventDefault()\n      e.stopPropagation() // capture phase: hold the click before next/link sees it, then replay it once the page is covered\n      setPhase('cover')\n      setTimeout(() => { replaying = true; a.click(); replaying = false }, 550) // next/link navigates (basePath, prefetch, its own handlers)\n    }\n    document.addEventListener('click', onClick, true)\n    return () => document.removeEventListener('click', onClick, true)\n  }, [reduce])\n  useEffect(() => { setPhase((p) => (p === 'cover' ? 'reveal' : p)) }, [path])\n  return (\n    <AnimatePresence onExitComplete={() => setPhase('idle')}>\n      {phase !== 'idle' && (\n        <motion.div key=\"blob\" aria-hidden className=\"pointer-events-none fixed inset-x-[-20%] z-[100] h-[140svh]\" style={{ background: color }}\n          initial={{ y: '100svh', borderRadius: '50% 50% 0 0 / 30% 30% 0 0' }}\n          animate={phase === 'cover' ? { y: '-20svh', borderRadius: '40% 60% 0 0 / 12% 18% 0 0' } : { y: '-160svh', borderRadius: '0 0 60% 40% / 0 0 30% 20%' }}\n          exit={{ opacity: 0 }} transition={{ duration: 0.55, ease: [0.76, 0, 0.24, 1] }}\n          onAnimationComplete={() => { if (phase === 'reveal') setPhase('idle') }} />\n      )}\n    </AnimatePresence>\n  )\n}\n",
  "brand-cursor": "'use client'\n// OpusKit piece — a brand cursor: a hand-drawn arrow (or your own SVG) replaces the system arrow on fine pointers.\n// Links and buttons keep the system pointer so clickable things still read as clickable. Original OpusKit code (MIT).\nimport { useEffect } from 'react'\n\nconst drawn = (fill: string) => `data:image/svg+xml,${encodeURIComponent(`<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"28\" height=\"32\" viewBox=\"0 0 28 32\"><path d=\"M3 2 C 9 12, 14 20, 17 28 L 19.5 19.5 L 27 17.5 C 19 12, 10 6, 3 2 Z\" fill=\"${fill}\" stroke=\"#111\" stroke-width=\"2\" stroke-linejoin=\"round\"/></svg>`)}`\n\nexport function BrandCursor({ src, hotspot = [3, 2] }: { src?: string; hotspot?: [number, number] }) {\n  useEffect(() => {\n    if (!matchMedia('(pointer: fine)').matches) return\n    const accent = getComputedStyle(document.documentElement).getPropertyValue('--color-chapter-1').trim() || getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim() || '#0038FF'\n    const url = src ?? drawn(accent)\n    const el = document.createElement('style')\n    el.textContent = `html{cursor:url(\"${url}\") ${hotspot[0]} ${hotspot[1]}, auto}a,button,[role=button],label,summary{cursor:pointer}`\n    document.head.appendChild(el)\n    return () => el.remove()\n  }, [src, hotspot])\n  return null\n}\n",
  "cookie-note": "'use client'\n// OpusKit piece — a cookie notice that looks like part of the brand: a small card with a two-part header (a place and\n// a label), plain words and one clear button. Remembers the answer. Original OpusKit code (MIT).\nimport { AnimatePresence, motion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function CookieNote({ text, place = 'Zone 1', label = 'Note', accept = 'Accept', decline = 'Only necessary', storageKey = 'cookie-choice' }: { text: string; place?: string; label?: string; accept?: string; decline?: string; storageKey?: string }) {\n  const [open, setOpen] = useState(false)\n  useEffect(() => { try { if (!localStorage.getItem(storageKey)) setOpen(true) } catch { setOpen(true) } }, [storageKey])\n  const answer = (v: string) => { try { localStorage.setItem(storageKey, v) } catch { /* private mode */ } setOpen(false) }\n  return (\n    <AnimatePresence>\n      {open && (\n        <motion.div role=\"dialog\" aria-live=\"polite\" aria-label={label} className=\"fixed bottom-4 right-4 z-50 w-[min(24rem,calc(100vw-2rem))] border border-(--color-border) bg-(--color-surface) text-(--color-text) shadow-(--shadow-card)\"\n          initial={{ y: 24, opacity: 0, rotate: 2 }} animate={{ y: 0, opacity: 1, rotate: 0 }} exit={{ y: 24, opacity: 0 }} transition={{ type: 'spring', stiffness: 260, damping: 22 }}>\n          <div className=\"type-utility flex items-center gap-3 border-b border-(--color-border) px-4 py-2.5 [font-family:var(--font-body)] [font-size:0.875rem]\">\n            <span>⌖ {place}</span><span aria-hidden className=\"h-4 w-px bg-(--color-border)\" /><span>✓ {label}</span>\n            <button type=\"button\" aria-label=\"Close\" onClick={() => answer('dismissed')} className=\"ml-auto px-1 text-lg leading-none\">×</button>\n          </div>\n          <p className=\"type-body px-4 pt-4 [font-size:0.9rem]\">{text}</p>\n          <div className=\"flex flex-wrap gap-2 px-4 pb-4 pt-4\">\n            <button type=\"button\" onClick={() => answer('all')} className=\"type-body bg-(--color-chapter-1,var(--color-accent)) px-4 py-2 text-(--color-background) [font-size:0.9rem]\">{accept} →</button>\n            <button type=\"button\" onClick={() => answer('necessary')} className=\"type-body px-3 py-2 underline underline-offset-4 [font-size:0.9rem]\">{decline}</button>\n          </div>\n        </motion.div>\n      )}\n    </AnimatePresence>\n  )\n}\n",
  "curtain-transition": "'use client'\n// OpusKit piece — page transition: clicking an internal link raises a plain panel over the page carrying the link's\n// words, then the panel keeps rising off the top to reveal the next page (under 700 ms in all). Mount once in the root\n// layout. Respects reduced motion (plain navigation). Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { usePathname } from 'next/navigation'\nimport { useEffect, useState } from 'react'\n\nconst EASE = [0.76, 0, 0.24, 1] as const\n\nexport function PageCurtain({ color = 'var(--color-text)' }: { color?: string }) {\n  const path = usePathname()\n  const reduce = useReducedMotion()\n  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle')\n  const [name, setName] = useState('')\n  useEffect(() => {\n    if (reduce) return\n    let replaying = false\n    const onClick = (e: MouseEvent) => {\n      if (replaying) return\n      const a = (e.target as HTMLElement).closest('a')\n      if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || a.target === '_blank' || a.hasAttribute('download')) return\n      const url = new URL(a.href, location.href)\n      if (url.origin !== location.origin || (url.pathname === location.pathname && url.hash)) return\n      e.preventDefault()\n      e.stopPropagation() // capture phase: hold the click before next/link sees it, then replay it once the page is covered\n      // A label that is drawn twice (TextRoll) carries its words in aria-label — prefer that over the doubled text.\n      const text = (a.getAttribute('aria-label') ?? a.querySelector('[aria-label]')?.getAttribute('aria-label') ?? a.textContent ?? '').trim().replace(/\\s+/g, ' ')\n      setName(text.length > 40 ? `${text.slice(0, 39)}…` : text)\n      setPhase('cover')\n      setTimeout(() => { replaying = true; a.click(); replaying = false }, 300) // next/link navigates (basePath, prefetch, its own handlers)\n      // Same pathname (only the query changed) never fires the reveal below — lift the curtain anyway.\n      setTimeout(() => setPhase((p) => (p === 'cover' ? 'reveal' : p)), 1200)\n    }\n    document.addEventListener('click', onClick, true)\n    return () => document.removeEventListener('click', onClick, true)\n  }, [reduce])\n  useEffect(() => { setPhase((p) => (p === 'cover' ? 'reveal' : p)) }, [path])\n  if (phase === 'idle') return null\n  return (\n    <motion.div aria-hidden className=\"pointer-events-none fixed inset-0 z-[100] grid place-items-center px-6\" style={{ background: color }}\n      initial={{ y: '100%' }} animate={{ y: phase === 'cover' ? '0%' : '-100%' }}\n      transition={{ duration: phase === 'cover' ? 0.3 : 0.35, ease: EASE }}\n      onAnimationComplete={() => { if (phase === 'reveal') setPhase('idle') }}>\n      <span className=\"text-center font-(family-name:--font-display) text-[clamp(2.5rem,8vw,7rem)] leading-none tracking-tight text-(--color-background)\">{name}</span>\n    </motion.div>\n  )\n}\n",
  "preloader": "'use client'\n// OpusKit piece — a designed preloader for the first page view of a visit: the brand name and a 0→100 count that\n// follows real loading (fonts and the page's own load), then the panel lifts away. Never longer than `maxMs`, never a\n// flash (≥ 600 ms). Reduced motion: no count — the name shows for the real load time, then fades. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useEffect, useLayoutEffect, useRef, useState } from 'react'\n\nconst KEY = 'opuskit-preloaded'\n\nexport function Preloader({ brand, maxMs = 2500 }: { brand: string; maxMs?: number }) {\n  const reduce = useReducedMotion()\n  // Rendered by default so the first paint is the panel, not the page; hidden at once when already seen this visit.\n  // ponytail: a full reload later in the same visit shows the panel until hydration; an inline head script would fix that.\n  const [phase, setPhase] = useState<'on' | 'leaving' | 'off'>('on')\n  const count = useRef<HTMLSpanElement>(null)\n  const shown = phase !== 'off'\n\n  useLayoutEffect(() => {\n    try { if (sessionStorage.getItem(KEY)) { setPhase('off'); return } } catch { /* storage blocked: once per mount */ }\n    const still = matchMedia('(prefers-reduced-motion: reduce)').matches\n    let fonts = 0, loaded = document.readyState === 'complete' ? 1 : 0, value = 0, raf = 0\n    const start = performance.now()\n    document.fonts?.ready.then(() => { fonts = 1 })\n    const onLoad = () => { loaded = 1 }\n    window.addEventListener('load', onLoad, { once: true })\n    const tick = (now: number) => {\n      const t = now - start\n      const target = fonts + loaded === 2 || t >= maxMs ? 100 : (fonts + loaded) * 50\n      value += (target - value) * 0.12\n      if (target === 100 && 100 - value < 0.5) value = 100\n      if (count.current) count.current.textContent = String(Math.round(value))\n      if (value === 100 && (still || t >= 600)) return setPhase('leaving')\n      raf = requestAnimationFrame(tick)\n    }\n    raf = requestAnimationFrame(tick)\n    return () => { cancelAnimationFrame(raf); window.removeEventListener('load', onLoad) }\n  }, [maxMs])\n\n  useEffect(() => {\n    if (!shown) return\n    const root = document.documentElement, prev = root.style.overflow\n    root.style.overflow = 'hidden'\n    return () => { root.style.overflow = prev }\n  }, [shown])\n\n  if (!shown) return null\n  return (\n    <motion.div role=\"status\" aria-label={`Loading ${brand}`} className=\"fixed inset-0 z-[110] flex flex-col justify-between bg-(--color-background) p-6 text-(--color-text) sm:p-10\"\n      initial={false} animate={phase === 'leaving' ? (reduce ? { opacity: 0 } : { y: '-100%' }) : {}}\n      transition={reduce ? { duration: 0.2 } : { duration: 0.6, ease: [0.76, 0, 0.24, 1] }}\n      onAnimationComplete={() => {\n        if (phase !== 'leaving') return\n        try { sessionStorage.setItem(KEY, '1') } catch { /* private mode */ }\n        setPhase('off')\n      }}>\n      <span className=\"font-(family-name:--font-display) text-[clamp(2.5rem,9vw,8rem)] leading-none tracking-tight\">{brand}</span>\n      <span ref={count} aria-hidden className=\"self-end motion-reduce:invisible font-(family-name:--font-utility) text-[clamp(1.5rem,4vw,3rem)] tabular-nums\">0</span>\n    </motion.div>\n  )\n}\n",
  "smooth-scroll": "'use client'\n// OpusKit piece — smooth scroll (Lenis, MIT): the wheel and trackpad glide instead of stepping, so scroll effects move\n// as one. Mouse/trackpad only — touch keeps the phone's own scroll. Off under reduced motion. In-page #anchors glide\n// too. Mount once in the root layout. Original OpusKit code (MIT).\nimport Lenis from 'lenis'\nimport { useEffect } from 'react'\n\nconst CSS = 'html.lenis,html.lenis body{height:auto}.lenis.lenis-smooth{scroll-behavior:auto!important}.lenis:not(.lenis-autoToggle).lenis-stopped{overflow:clip}.lenis [data-lenis-prevent],.lenis [data-lenis-prevent-wheel],.lenis [data-lenis-prevent-touch],.lenis [data-lenis-prevent-vertical],.lenis [data-lenis-prevent-horizontal]{overscroll-behavior:contain}.lenis.lenis-smooth iframe{pointer-events:none}.lenis.lenis-autoToggle{transition-property:overflow;transition-duration:1ms;transition-behavior:allow-discrete}'\n\nexport function SmoothScroll({ lerp = 0.1 }: { lerp?: number }) {\n  useEffect(() => {\n    const fine = matchMedia('(pointer: fine)'), still = matchMedia('(prefers-reduced-motion: reduce)')\n    let lenis: Lenis | undefined\n    const sync = () => {\n      const want = fine.matches && !still.matches\n      if (want && !lenis) lenis = new Lenis({ lerp, anchors: true, autoRaf: true }) // autoRaf: Lenis runs its own requestAnimationFrame loop\n      else if (!want && lenis) { lenis.destroy(); lenis = undefined }\n    }\n    sync()\n    fine.addEventListener('change', sync)\n    still.addEventListener('change', sync)\n    return () => { fine.removeEventListener('change', sync); still.removeEventListener('change', sync); lenis?.destroy() }\n  }, [lerp])\n  return <style>{CSS}</style>\n}\n",
  "ambient-sound": "'use client'\n// OpusKit piece — a quiet sound loop with an always-visible switch (bottom-left by default; `placement` moves it, e.g.\n// into the menu bar, so it never sits on top of text). Off by default and never autoplays:\n// a remembered \"on\" waits for the visitor's first tap or key. Fades in and out, pauses while the tab is hidden.\n// Reduced motion: the little bars stay still. Original OpusKit code (MIT).\nimport { useEffect, useRef, useState } from 'react'\n\nconst KEY = 'opuskit-sound'\nconst CSS = '@keyframes opuskit-bars{from{transform:scaleY(.3)}to{transform:scaleY(1)}}@media (prefers-reduced-motion:no-preference){.opuskit-bars[data-playing]>span{animation:opuskit-bars .9s ease-in-out infinite alternate}}'\n\nexport function AmbientSound({ src, label = 'Sound', volume = 0.4, placement = 'fixed bottom-4 left-4 z-[90]' }: { src: string; label?: string; volume?: number; /** Position classes for the switch; pass '' to place it in the flow (e.g. inside the menu bar). */ placement?: string }) {\n  const [on, setOn] = useState(false)\n  const [playing, setPlaying] = useState(false)\n  const audio = useRef<HTMLAudioElement | null>(null)\n  const fade = useRef(0)\n  const wanted = useRef(false) // the visitor's choice, for listeners\n  const started = useRef(false) // the page has had a user gesture, so play() is allowed\n\n  const ramp = (to: number, after?: () => void) => {\n    const a = audio.current\n    if (!a) return after?.()\n    cancelAnimationFrame(fade.current)\n    const from = a.volume, start = performance.now()\n    const step = (now: number) => {\n      const k = Math.min(1, Math.max(0, (now - start) / 800)) // the first frame can land just before start\n      a.volume = Math.min(1, Math.max(0, from + (to - from) * k))\n      if (k < 1) fade.current = requestAnimationFrame(step)\n      else after?.()\n    }\n    fade.current = requestAnimationFrame(step)\n  }\n  const play = () => {\n    started.current = true\n    if (!src) return\n    const a = (audio.current ??= Object.assign(new Audio(src), { loop: true, volume: 0 }))\n    a.play().then(() => { setPlaying(true); ramp(volume) }).catch(() => { /* blocked or missing file: stay quiet */ })\n  }\n  const stop = () => { setPlaying(false); ramp(0, () => audio.current?.pause()) }\n\n  useEffect(() => {\n    let saved = false\n    try { saved = localStorage.getItem(KEY) === 'on' } catch { /* private mode */ }\n    if (!saved) return\n    setOn(true)\n    wanted.current = true\n    // Browsers block sound until a gesture; a press on the switch itself is handled by its own click.\n    const first = (e: Event) => {\n      if ((e.target as HTMLElement | null)?.closest?.('[data-opuskit-sound]')) return\n      remove()\n      if (wanted.current && !started.current) play()\n    }\n    const remove = () => { removeEventListener('pointerdown', first); removeEventListener('keydown', first) }\n    addEventListener('pointerdown', first)\n    addEventListener('keydown', first)\n    return remove\n  }, [])\n\n  useEffect(() => {\n    const onVisibility = () => {\n      const a = audio.current\n      if (!a || !wanted.current) return\n      if (document.hidden) a.pause()\n      else a.play().catch(() => {})\n    }\n    document.addEventListener('visibilitychange', onVisibility)\n    return () => { document.removeEventListener('visibilitychange', onVisibility); cancelAnimationFrame(fade.current); audio.current?.pause() }\n  }, [])\n\n  const toggle = () => {\n    const next = !on\n    setOn(next)\n    wanted.current = next\n    try { localStorage.setItem(KEY, next ? 'on' : 'off') } catch { /* private mode */ }\n    if (next) play()\n    else stop()\n  }\n\n  return (\n    <>\n      <button type=\"button\" data-opuskit-sound aria-pressed={on} aria-label={`${label}: ${on ? 'on' : 'off'}`} onClick={toggle}\n        className={`${placement} inline-flex min-h-11 min-w-11 items-center gap-2.5 rounded-(--radius-button,999px) border border-(--color-border) bg-(--color-background) px-4 font-(family-name:--font-utility) text-sm text-(--color-text)`}>\n        <span aria-hidden className=\"opuskit-bars flex h-3 items-end gap-0.5\" data-playing={playing || undefined}>\n          {[0, 1, 2, 3].map((i) => <span key={i} className=\"h-full w-0.5 origin-bottom bg-current\" style={{ transform: 'scaleY(.3)', animationDelay: `${i * -0.22}s` }} />)}\n        </span>\n        {label} {on ? 'on' : 'off'}\n      </button>\n      <style>{CSS}</style>\n    </>\n  )\n}\n",
}

export const blockSource: Partial<Record<SectionId, string>> = {
  "intro": "// OpusKit section — Intro: what this is and who it is for, in one statement. Uses the recipe tokens only.\nexport function IntroSection({ label, statement, body }: { label?: string; statement: string; body?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-6 md:grid-cols-12\">\n        {label && <p className=\"type-utility text-(--color-muted) md:col-span-3\">{label}</p>}\n        <div className={label ? 'md:col-span-8' : 'md:col-span-9'}>\n          <p className=\"type-heading text-balance [font-size:clamp(1.75rem,3.6vw,3.25rem)]\">{statement}</p>\n          {body && <p className=\"type-body mt-6 max-w-[60ch] text-(--color-muted)\">{body}</p>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "manifesto": "// OpusKit section — Manifesto: the point of view, display-size, spanning the grid.\nexport function ManifestoSection({ statement, attribution }: { statement: string; attribution?: string }) {\n  return (\n    <section className=\"px-5 py-28 md:px-10 md:py-40\">\n      <blockquote className=\"mx-auto max-w-[1440px]\">\n        <p className=\"type-display text-balance [font-size:clamp(2.5rem,7vw,7rem)]\">{statement}</p>\n        {attribution && <footer className=\"type-utility mt-8 text-(--color-muted)\">{attribution}</footer>}\n      </blockquote>\n    </section>\n  )\n}\n",
  "featured-work": "import type { ElementType } from 'react'\n// OpusKit section — Featured Work: 3–6 best projects, alternating large and small so the rhythm never repeats.\nexport type Project = { title: string; meta: string; image: string; alt: string; href: string }\n\nexport function FeaturedWorkSection({ link: L = 'a', title, projects }: { link?: ElementType; title: string; projects: Project[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 grid gap-x-6 gap-y-16 md:grid-cols-12\">\n          {projects.map((p, i) => (\n            <li key={p.href} className={i % 3 === 0 ? 'md:col-span-7' : i % 3 === 1 ? 'md:col-span-5 md:mt-24' : 'md:col-span-6 md:col-start-4'}>\n              <L href={p.href} className=\"group block\">\n                <div className=\"overflow-hidden rounded-(--radius-media)\"><img src={p.image} alt={p.alt} loading=\"lazy\" className={`w-full object-cover transition-transform duration-500 group-hover:scale-[1.03] ${i % 3 === 1 ? 'aspect-[4/5]' : 'aspect-[3/2]'}`} /></div>\n                <div className=\"mt-4 flex items-baseline justify-between gap-4\">\n                  <h3 className=\"type-heading [font-size:clamp(1.25rem,1.8vw,1.6rem)] group-hover:underline group-hover:underline-offset-4\">{p.title}</h3>\n                  <p className=\"type-utility shrink-0 text-(--color-muted)\">{p.meta}</p>\n                </div>\n              </L>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "case-study": "import type { ElementType } from 'react'\n// OpusKit section — Case Study preview: one project in depth — wide media, facts, then problem / approach / result.\nexport function CaseStudySection({ link: L = 'a', title, image, alt, facts, paragraphs, href }: { link?: ElementType; title: string; image: string; alt: string; facts: { label: string; value: string }[]; paragraphs: string[]; href?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[21/9] w-full rounded-(--radius-media) object-cover\" />\n        <div className=\"mt-10 grid gap-10 md:grid-cols-12\">\n          <div className=\"md:col-span-4\">\n            <h2 className=\"type-heading\">{title}</h2>\n            <dl className=\"mt-6 grid grid-cols-2 gap-4 md:grid-cols-1\">\n              {facts.map((f) => <div key={f.label}><dt className=\"type-utility text-(--color-muted)\">{f.label}</dt><dd className=\"type-body mt-1\">{f.value}</dd></div>)}\n            </dl>\n          </div>\n          <div className=\"type-body space-y-5 md:col-span-7 md:col-start-6\">\n            {paragraphs.map((p, i) => <p key={i} className=\"max-w-[62ch]\">{p}</p>)}\n            {href && <L href={href} className=\"inline-block underline underline-offset-4\">Read the full case study</L>}\n          </div>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "services": "import type { ElementType } from 'react'\n// OpusKit section — Services: what you offer, one row each, with rules between; the hovered row lifts.\nexport function ServicesSection({ link: L = 'a', title, items }: { link?: ElementType; title: string; items: { name: string; line: string; href?: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading md:col-span-4\">{title}</h2>\n        <ul className=\"border-t border-(--color-border) md:col-span-8\">\n          {items.map((s) => (\n            <li key={s.name} className=\"group grid gap-2 border-b border-(--color-border) py-6 transition-colors hover:bg-(--color-surface) md:grid-cols-2 md:px-4\">\n              <h3 className=\"type-heading [font-size:clamp(1.25rem,2vw,1.75rem)]\">{s.href ? <L href={s.href} className=\"hover:underline hover:underline-offset-4\">{s.name}</L> : s.name}</h3>\n              <p className=\"type-body text-(--color-muted)\">{s.line}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "process": "// OpusKit section — Process: how working together goes, 3–5 real steps (numbered, because it is a real sequence).\nexport function ProcessSection({ title, steps }: { title: string; steps: { name: string; text: string; duration?: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ol className=\"mt-12 grid gap-10 md:grid-cols-[repeat(auto-fit,minmax(14rem,1fr))]\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"border-t border-(--color-text) pt-5\">\n              <p className=\"type-display [font-size:clamp(2.5rem,4vw,3.5rem)]\">{i + 1}</p>\n              <h3 className=\"type-heading mt-4 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n              {s.duration && <p className=\"type-utility mt-3\">{s.duration}</p>}\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "how-it-works": "// OpusKit section — How It Works: 3–4 steps with a real visual each, side by side on desktop.\nexport function HowItWorksSection({ title, steps }: { title: string; steps: { name: string; text: string; image?: string; alt?: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading max-w-[24ch]\">{title}</h2>\n        <ol className=\"mt-12 grid gap-6 md:grid-cols-3\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-5 shadow-(--shadow-card)\">\n              {s.image && <img src={s.image} alt={s.alt ?? ''} loading=\"lazy\" className=\"mb-5 aspect-[4/3] w-full rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-utility text-(--color-accent)\">Step {i + 1}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "about": "// OpusKit section — About: a real face and a point of view. Portrait, statement, short bio.\nexport function AboutSection({ title, image, alt, statement, bio }: { title: string; image: string; alt: string; statement: string; bio: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] items-end gap-10 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[4/5] w-full rounded-(--radius-media) object-cover md:col-span-5\" />\n        <div className=\"md:col-span-6 md:col-start-7\">\n          <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n          <p className=\"type-heading mt-4 text-balance [font-size:clamp(1.5rem,3vw,2.6rem)]\">{statement}</p>\n          <p className=\"type-body mt-6 max-w-[58ch] text-(--color-muted)\">{bio}</p>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "gallery": "// OpusKit section — Gallery: a mixed-size grid that keeps each photo's own shape; sparse captions.\nexport type GalleryPhoto = { src: string; alt: string; caption?: string }\n\nexport function GallerySection({ title, photos }: { title?: string; photos: GalleryPhoto[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        {title && <h2 className=\"type-heading mb-10\">{title}</h2>}\n        <ul className=\"columns-2 gap-4 md:columns-3 [&>li]:mb-4\">\n          {photos.map((p) => (\n            <li key={p.src} className=\"break-inside-avoid\">\n              <figure>\n                <img src={p.src} alt={p.alt} loading=\"lazy\" className=\"w-full rounded-(--radius-media) object-cover\" />\n                {p.caption && <figcaption className=\"type-utility mt-2 text-(--color-muted)\">{p.caption}</figcaption>}\n              </figure>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "editorial-story": "// OpusKit section — Editorial Story: headline, a narrow reading column and one large image with a margin caption.\nexport function EditorialStorySection({ title, image, alt, caption, paragraphs }: { title: string; image: string; alt: string; caption?: string; paragraphs: string[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <article className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <h2 className=\"type-display text-balance [font-size:clamp(2.2rem,5vw,4.5rem)] md:col-span-10\">{title}</h2>\n        <div className=\"type-body space-y-5 md:col-span-5 md:col-start-2 [&>p:first-child]:[font-size:1.15em]\">\n          {paragraphs.map((p, i) => <p key={i} className=\"max-w-[60ch]\">{p}</p>)}\n        </div>\n        <figure className=\"md:col-span-5 md:col-start-8\">\n          <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[4/5] w-full rounded-(--radius-media) object-cover\" />\n          {caption && <figcaption className=\"type-utility mt-3 text-(--color-muted)\">{caption}</figcaption>}\n        </figure>\n      </article>\n    </section>\n  )\n}\n",
  "testimonials": "// OpusKit section — Testimonials: what real people said, in their words, with their name and role. One large quote\n// leads; the rest sit in a quiet row. No stars, no stock faces.\nexport function TestimonialsSection({ title, quotes }: { title: string; quotes: { quote: string; name: string; role: string }[] }) {\n  const [lead, ...rest] = quotes\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        {lead && (\n          <figure className=\"mt-8 max-w-[34ch] md:max-w-[28ch]\">\n            <blockquote className=\"type-heading text-balance [font-size:clamp(1.6rem,3.6vw,3rem)]\">“{lead.quote}”</blockquote>\n            <figcaption className=\"type-body mt-6 text-(--color-muted)\">{lead.name}, {lead.role}</figcaption>\n          </figure>\n        )}\n        {rest.length > 0 && (\n          <ul className=\"mt-16 grid gap-10 border-t border-(--color-border) pt-10 md:grid-cols-3\">\n            {rest.map((q) => (\n              <li key={q.name}>\n                <blockquote className=\"type-body\">“{q.quote}”</blockquote>\n                <p className=\"type-utility mt-4 text-(--color-muted)\">{q.name}, {q.role}</p>\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </section>\n  )\n}\n",
  "team": "// OpusKit section — Team: the people, each with a real photo, name, role and one line in their own voice.\nexport function TeamSection({ title, people }: { title: string; people: { name: string; role: string; line?: string; image: string; alt: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading [font-size:clamp(1.6rem,3vw,2.6rem)]\">{title}</h2>\n        <ul className=\"mt-10 grid grid-cols-2 gap-x-5 gap-y-10 md:grid-cols-4\">\n          {people.map((p) => (\n            <li key={p.name}>\n              <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-[4/5] w-full rounded-(--radius-media) object-cover\" />\n              <p className=\"type-body mt-4 font-medium\">{p.name}</p>\n              <p className=\"type-utility text-(--color-muted)\">{p.role}</p>\n              {p.line && <p className=\"type-body mt-2 text-(--color-muted)\">{p.line}</p>}\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "stats": "// OpusKit section — Stats: three or four real numbers that prove something, each with a plain label.\n// Numbers are set big in the display face; nothing counts up (a number people can read at once is the point).\nexport function StatsSection({ title, stats, note }: { title?: string; stats: { value: string; label: string }[]; note?: string }) {\n  return (\n    <section className=\"px-5 py-20 md:px-10 md:py-28\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        {title && <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>}\n        <dl className=\"mt-8 grid grid-cols-2 gap-y-10 border-t border-(--color-border) pt-8 md:grid-cols-4\">\n          {stats.map((s) => (\n            <div key={s.label} className=\"flex flex-col pr-6\">\n              <dt className=\"type-utility order-2 mt-3 text-(--color-muted)\">{s.label}</dt>\n              <dd className=\"type-display order-1 [font-size:clamp(2.4rem,5vw,4.5rem)] leading-none\">{s.value}</dd>\n            </div>\n          ))}\n        </dl>\n        {note && <p className=\"type-body mt-8 max-w-[60ch] text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "clients": "// OpusKit section — Clients: real names only, set as type (no fake logos).\nexport function ClientsSection({ title, names }: { title: string; names: string[] }) {\n  return (\n    <section className=\"px-5 py-20 md:px-10 md:py-28\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 grid grid-cols-2 border-l border-t border-(--color-border) md:grid-cols-4\">\n          {names.map((n) => <li key={n} className=\"type-heading border-b border-r border-(--color-border) px-5 py-8 [font-size:clamp(1.05rem,1.6vw,1.35rem)]\">{n}</li>)}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "menu": "// OpusKit section — Menu: real HTML (readable, searchable, translatable) in two columns, prices aligned.\nexport type MenuGroup = { name: string; items: { name: string; description?: string; price: string }[] }\n\nexport function MenuSection({ title, groups, note }: { title: string; groups: MenuGroup[]; note?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <div className=\"mt-12 grid gap-x-16 gap-y-12 md:grid-cols-2\">\n          {groups.map((g) => (\n            <div key={g.name}>\n              <h3 className=\"type-utility border-b border-(--color-text) pb-3\">{g.name}</h3>\n              <ul>\n                {g.items.map((it) => (\n                  <li key={it.name} className=\"border-b border-(--color-border) py-4\">\n                    <p className=\"flex items-baseline gap-3\"><span className=\"type-heading [font-size:1.15rem]\">{it.name}</span><span aria-hidden className=\"flex-1 border-b border-dotted border-(--color-border)\" /><span className=\"type-body tabular-nums\">{it.price}</span></p>\n                    {it.description && <p className=\"type-body mt-1 max-w-[50ch] text-(--color-muted)\">{it.description}</p>}\n                  </li>\n                ))}\n              </ul>\n            </div>\n          ))}\n        </div>\n        {note && <p className=\"type-utility mt-10 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "reservation": "// OpusKit section — Reservation: a short invitation, the practical facts, and the booking form beside them. The form is\n// the project's own, built from shadcn/ui (a Calendar in a Popover for the day, Selects for time and party size) and passed\n// in as `form`; it hands off to the booking link or email with the details filled in — no fake confirmation. This section\n// only lays it out, so no plain browser date, time or number input ships.\nimport type { ReactNode } from 'react'\n\nexport function ReservationSection({ title, text, hours, phone, form }: { title: string; text: string; hours: string[]; phone: string; form: ReactNode }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-12 md:grid-cols-12\">\n        <div className=\"md:col-span-5\">\n          <h2 className=\"type-heading\">{title}</h2>\n          <p className=\"type-body mt-4 text-(--color-muted)\">{text}</p>\n          <ul className=\"type-body mt-6 space-y-1\">{hours.map((h) => <li key={h}>{h}</li>)}</ul>\n          <p className=\"type-body mt-4\">Rather call? <a href={`tel:${phone.replace(/\\s/g, '')}`} className=\"underline underline-offset-4\">{phone}</a></p>\n        </div>\n        <div className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-6 shadow-(--shadow-card) md:col-span-6 md:col-start-7 md:self-start\">{form}</div>\n      </div>\n    </section>\n  )\n}\n",
  "location": "// OpusKit section — Location: address, hours, how to get there, one exterior photo, and a real map link.\nexport function LocationSection({ title, address, hours, notes, mapUrl, image, alt }: { title: string; address: string; hours: string[]; notes?: string; mapUrl: string; image: string; alt: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[4/3] w-full rounded-(--radius-media) object-cover md:col-span-7\" />\n        <div className=\"md:col-span-4 md:col-start-9\">\n          <h2 className=\"type-heading\">{title}</h2>\n          <address className=\"type-body mt-5 whitespace-pre-line not-italic\">{address}</address>\n          <ul className=\"type-body mt-5 space-y-1 text-(--color-muted)\">{hours.map((h) => <li key={h}>{h}</li>)}</ul>\n          {notes && <p className=\"type-body mt-5 text-(--color-muted)\">{notes}</p>}\n          <a href={mapUrl} target=\"_blank\" rel=\"noreferrer\" className=\"type-body mt-6 inline-block rounded-(--radius-button) border border-(--color-text) px-5 py-2.5\">Open in maps</a>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "collection": "import type { ElementType } from 'react'\n// OpusKit section — Collection: a full-height image with the season's title, then its key pieces.\nexport type Piece = { name: string; price: string; image: string; alt: string; href: string }\n\nexport function CollectionSection({ link: L = 'a', season, title, text, image, alt, pieces }: { link?: ElementType; season: string; title: string; text: string; image: string; alt: string; pieces: Piece[] }) {\n  return (\n    <section>\n      <div className=\"relative min-h-[90svh] overflow-hidden\">\n        <img src={image} alt={alt} className=\"absolute inset-0 size-full object-cover\" />\n        <div className=\"absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/55 to-transparent px-5 pb-10 pt-32 text-white md:px-10\">\n          <p className=\"type-utility\">{season}</p>\n          <h2 className=\"type-display mt-2 [font-size:clamp(2.5rem,8vw,7rem)]\">{title}</h2>\n          <p className=\"type-body mt-4 max-w-[48ch] opacity-90\">{text}</p>\n        </div>\n      </div>\n      <ul className=\"mx-auto grid max-w-[1440px] grid-cols-2 gap-4 px-5 py-16 md:grid-cols-3 md:px-10\">\n        {pieces.map((p) => (\n          <li key={p.href}><L href={p.href} className=\"group block\">\n            <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-[4/5] w-full rounded-(--radius-media) object-cover\" />\n            <p className=\"mt-3 flex justify-between gap-3\"><span className=\"type-body group-hover:underline group-hover:underline-offset-4\">{p.name}</span><span className=\"type-body tabular-nums text-(--color-muted)\">{p.price}</span></p>\n          </L></li>\n        ))}\n      </ul>\n    </section>\n  )\n}\n",
  "lookbook": "import type { ElementType } from 'react'\n// OpusKit section — Lookbook: magazine spreads, a large and a small photo per look, with what is worn.\nexport type Look = { number: string; image: string; alt: string; detail?: string; detailAlt?: string; pieces: string; href?: string }\n\nexport function LookbookSection({ link: L = 'a', title, looks }: { link?: ElementType; title?: string; looks: Look[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px] space-y-24\">\n        {title && <h2 className=\"type-heading\">{title}</h2>}\n        {looks.map((l, i) => (\n          <article key={l.number} className={`grid items-end gap-6 md:grid-cols-12 ${i % 2 ? 'md:[direction:rtl]' : ''}`}>\n            <img src={l.image} alt={l.alt} loading=\"lazy\" className=\"aspect-[3/4] w-full rounded-(--radius-media) object-cover md:col-span-7 [direction:ltr]\" />\n            <div className=\"md:col-span-4 [direction:ltr]\">\n              {l.detail && <img src={l.detail} alt={l.detailAlt ?? ''} loading=\"lazy\" className=\"mb-6 aspect-square w-2/3 rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-display [font-size:clamp(2rem,4vw,3.5rem)]\">Look {l.number}</p>\n              <p className=\"type-body mt-3 text-(--color-muted)\">{l.pieces}</p>\n              {l.href && <L href={l.href} className=\"type-body mt-4 inline-block underline underline-offset-4\">Shop the look</L>}\n            </div>\n          </article>\n        ))}\n      </div>\n    </section>\n  )\n}\n",
  "product-grid": "import type { ElementType } from 'react'\n// OpusKit section — Product Grid: browse and choose. Even tiles, one ratio, second photo on hover, honest availability.\nexport type Product = { name: string; price: string; image: string; alt: string; hoverImage?: string; href: string; soldOut?: boolean }\n\nexport function ProductGridSection({ link: L = 'a', title, products }: { link?: ElementType; title: string; products: Product[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-10 grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 xl:grid-cols-4\">\n          {products.map((p) => (\n            <li key={p.href}>\n              <L href={p.href} className=\"group block\">\n                <div className=\"relative overflow-hidden rounded-(--radius-media) bg-(--color-surface)\">\n                  <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-[4/5] w-full object-cover\" />\n                  {p.hoverImage && <img src={p.hoverImage} alt=\"\" loading=\"lazy\" className=\"absolute inset-0 size-full object-cover opacity-0 transition-opacity duration-300 group-hover:opacity-100\" />}\n                  {p.soldOut && <span className=\"type-utility absolute left-3 top-3 rounded-(--radius-button) bg-(--color-background) px-2 py-1\">Sold out</span>}\n                </div>\n                <p className=\"mt-3 flex justify-between gap-3\"><span className=\"type-body group-hover:underline group-hover:underline-offset-4\">{p.name}</span><span className=\"type-body tabular-nums text-(--color-muted)\">{p.price}</span></p>\n              </L>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "product-highlight": "import type { ElementType } from 'react'\n// OpusKit section — Product Highlight: one product (or feature) in depth — large media and 3–4 real details.\nexport function ProductHighlightSection({ link: L = 'a', name, text, image, alt, details, action }: { link?: ElementType; name: string; text: string; image: string; alt: string; details: { label: string; value: string }[]; action: { label: string; href: string } }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] items-center gap-12 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-square w-full rounded-(--radius-media) bg-(--color-surface) object-cover md:col-span-7\" />\n        <div className=\"md:col-span-4 md:col-start-9\">\n          <h2 className=\"type-display [font-size:clamp(2.2rem,4.5vw,4rem)]\">{name}</h2>\n          <p className=\"type-body mt-4 text-(--color-muted)\">{text}</p>\n          <dl className=\"mt-8 divide-y divide-(--color-border) border-y border-(--color-border)\">\n            {details.map((d) => <div key={d.label} className=\"flex justify-between gap-4 py-3\"><dt className=\"type-utility text-(--color-muted)\">{d.label}</dt><dd className=\"type-body text-right\">{d.value}</dd></div>)}\n          </dl>\n          <L href={action.href} className=\"type-body mt-8 inline-block rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background)\">{action.label}</L>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "feature-grid": "// OpusKit section — Features: 3–6 capabilities in concrete language, each with a real visual when there is one.\nexport function FeatureGridSection({ title, features }: { title: string; features: { name: string; text: string; image?: string; alt?: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading max-w-[24ch]\">{title}</h2>\n        <ul className=\"mt-12 grid gap-px overflow-hidden rounded-(--radius-card) border border-(--color-border) bg-(--color-border) md:grid-cols-2 xl:grid-cols-3\">\n          {features.map((f) => (\n            <li key={f.name} className=\"bg-(--color-background) p-6 md:p-8\">\n              {f.image && <img src={f.image} alt={f.alt ?? ''} loading=\"lazy\" className=\"mb-6 aspect-[16/10] w-full rounded-(--radius-media) object-cover\" />}\n              <h3 className=\"type-heading [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{f.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{f.text}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "pricing": "import type { ElementType } from 'react'\n// OpusKit section — Pricing: 2–3 plans side by side, one recommended, everything each includes in plain words.\nexport type Plan = { name: string; price: string; period?: string; line?: string; features: string[]; action: { label: string; href: string }; recommended?: boolean }\n\nexport function PricingSection({ link: L = 'a', title, plans, note }: { link?: ElementType; title: string; plans: Plan[]; note?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 grid gap-6 md:grid-cols-[repeat(auto-fit,minmax(16rem,1fr))]\">\n          {plans.map((p) => (\n            <li key={p.name} className={`flex flex-col rounded-(--radius-card) border bg-(--color-surface) p-7 shadow-(--shadow-card) ${p.recommended ? 'border-(--color-accent) ring-1 ring-(--color-accent)' : 'border-(--color-border)'}`}>\n              <div className=\"flex items-baseline justify-between gap-3\"><h3 className=\"type-heading [font-size:1.3rem]\">{p.name}</h3>{p.recommended && <span className=\"type-utility text-(--color-accent)\">Recommended</span>}</div>\n              {p.line && <p className=\"type-body mt-2 text-(--color-muted)\">{p.line}</p>}\n              <p className=\"mt-6\"><span className=\"type-display [font-size:clamp(2.5rem,4vw,3.5rem)]\">{p.price}</span>{p.period && <span className=\"type-body text-(--color-muted)\"> / {p.period}</span>}</p>\n              <ul className=\"type-body mt-6 flex-1 space-y-2\">{p.features.map((f) => <li key={f} className=\"border-t border-(--color-border) pt-2\">{f}</li>)}</ul>\n              <L href={p.action.href} className={`type-body mt-8 rounded-(--radius-button) px-5 py-3 text-center ${p.recommended ? 'bg-(--color-primary) text-(--color-background)' : 'border border-(--color-text)'}`}>{p.action.label}</L>\n            </li>\n          ))}\n        </ul>\n        {note && <p className=\"type-utility mt-8 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "faq": "// OpusKit section — FAQ: real questions in a narrow column beside the title. The list itself is the project's own\n// shadcn/ui Accordion (type=\"single\" collapsible), passed as children and styled through the tokens — this section only\n// lays it out, so no hand-made disclosure ships.\nimport type { ReactNode } from 'react'\n\nexport function FaqSection({ title, children }: { title: string; children: ReactNode }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading md:col-span-4\">{title}</h2>\n        <div className=\"border-t border-(--color-border) md:col-span-7 md:col-start-6\">{children}</div>\n      </div>\n    </section>\n  )\n}\n",
  "journal": "import type { ElementType } from 'react'\n// OpusKit section — Journal: the latest 3 entries as an editorial list — date, category, title.\nexport type Entry = { title: string; date: string; category: string; href: string; image?: string; alt?: string }\n\nexport function JournalSection({ link: L = 'a', title, entries, allHref }: { link?: ElementType; title: string; entries: Entry[]; allHref?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <div className=\"flex items-baseline justify-between gap-4\"><h2 className=\"type-heading\">{title}</h2>{allHref && <L href={allHref} className=\"type-body underline underline-offset-4\">All entries</L>}</div>\n        <ul className=\"mt-10 grid gap-8 md:grid-cols-3\">\n          {entries.map((e) => (\n            <li key={e.href}><L href={e.href} className=\"group block\">\n              {e.image && <img src={e.image} alt={e.alt ?? ''} loading=\"lazy\" className=\"mb-4 aspect-[3/2] w-full rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-utility text-(--color-muted)\"><time>{e.date}</time>, {e.category}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.15rem,1.6vw,1.45rem)] group-hover:underline group-hover:underline-offset-4\">{e.title}</h3>\n            </L></li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "contact-cta": "import type { ElementType } from 'react'\n// OpusKit section — Closing CTA: one headline in the brand voice (optionally two voices), one action, and a real way\n// to reach you. `inverse` ends the page on the text colour — a dark full-screen close.\nexport function ContactCtaSection({ link: L = 'a', headline, quiet, action, email, inverse = false }: { link?: ElementType; headline: string; quiet?: string; action: { label: string; href: string }; email?: string; inverse?: boolean }) {\n  return (\n    <section className={`px-5 py-28 md:px-10 md:py-40 ${inverse ? 'bg-(--color-text) text-(--color-background)' : ''}`}>\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-display text-balance [font-size:clamp(2.75rem,8vw,7.5rem)]\">{headline}{quiet && <span className=\"block font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\">{quiet}</span>}</h2>\n        <div className=\"mt-10 flex flex-wrap items-center gap-x-8 gap-y-4\">\n          <L href={action.href} className={`type-body rounded-(--radius-button) px-7 py-3.5 ${inverse ? 'bg-(--color-chapter-2,var(--color-accent)) text-(--color-text)' : 'bg-(--color-primary) text-(--color-background)'}`}>{action.label}</L>\n          {email && <a href={`mailto:${email}`} className=\"type-body underline underline-offset-4\">{email}</a>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "chapters": "// OpusKit section — Colour Chapters: each offer is a chapter; its text sits on the neutral half, the other half is a\n// full field in that chapter's colour (--color-chapter-1..3, the recipe's colour chapters) holding a sticky photo or clip.\nexport type Chapter = { eyebrow: string; title: string; text: string; media: { src: string; alt: string; video?: boolean }; sticker?: { src: string; alt: string } }\n\nexport function ColourChaptersSection({ chapters }: { chapters: Chapter[] }) {\n  return (\n    <section>\n      {chapters.map((c, i) => (\n        <article key={c.title} className=\"grid md:min-h-[140svh] md:grid-cols-2\">\n          <div className=\"md:order-2\">\n            <div className=\"grid place-items-center px-8 py-16 md:sticky md:top-0 md:h-svh md:px-14\" style={{ background: `var(--color-chapter-${(i % 3) + 1}, var(--color-accent))` }}>\n              {c.media.video\n                ? <video src={c.media.src} autoPlay muted loop playsInline aria-label={c.media.alt} className=\"aspect-[4/5] w-full max-w-[34rem] rounded-(--radius-media) object-cover\" />\n                : <img src={c.media.src} alt={c.media.alt} loading=\"lazy\" className=\"aspect-[4/5] w-full max-w-[34rem] rounded-(--radius-media) object-cover\" />}\n            </div>\n          </div>\n          <div className=\"relative grid content-start px-6 py-20 text-center md:sticky md:top-0 md:h-svh md:content-center md:px-16\">\n            {c.sticker && <img src={c.sticker.src} alt={c.sticker.alt} loading=\"lazy\" className=\"absolute left-6 top-24 w-28 -rotate-6 md:left-10 md:w-36\" />}\n            <p className=\"type-utility\">{c.eyebrow}</p>\n            <h2 className=\"type-display mt-2 [font-size:clamp(3rem,7vw,6rem)]\">{c.title}</h2>\n            <p className=\"type-body mx-auto mt-5 max-w-[44ch]\">{c.text}</p>\n          </div>\n        </article>\n      ))}\n    </section>\n  )\n}\n",
  "feature-rows": "import type { ElementType } from 'react'\n// OpusKit section — Feature rows: one capability or offer per row, picture beside words, sides alternating on desktop.\nexport function FeatureRowsSection({ link: L = 'a', title, rows }: { link?: ElementType; title?: string; rows: { name: string; text: string; image?: string; alt?: string; link?: { label: string; href: string } }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        {title && <h2 className=\"type-heading mb-16 max-w-[24ch] md:mb-24\">{title}</h2>}\n        <ul className=\"space-y-20 md:space-y-32\">\n          {rows.map((r, i) => (\n            <li key={r.name} className=\"grid items-center gap-8 md:grid-cols-12 md:gap-10\">\n              {r.image && <img src={r.image} alt={r.alt ?? ''} loading=\"lazy\" className={`aspect-[4/3] w-full rounded-(--radius-media) bg-(--color-surface) object-cover md:col-span-7 ${i % 2 ? 'md:order-2 md:col-start-6' : ''}`} />}\n              <div className={!r.image ? 'md:col-span-8' : i % 2 ? 'md:order-1 md:col-span-4 md:col-start-1' : 'md:col-span-4 md:col-start-9'}>\n                <h3 className=\"type-heading text-balance [font-size:clamp(1.5rem,2.6vw,2.4rem)]\">{r.name}</h3>\n                <p className=\"type-body mt-4 max-w-[46ch] text-(--color-muted)\">{r.text}</p>\n                {r.link && <L href={r.link.href} className=\"type-body mt-6 inline-block underline underline-offset-4\">{r.link.label}</L>}\n              </div>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "newsletter": "// OpusKit section — Newsletter: one reason to subscribe, an email field and a button, and a plain note on how often.\nexport function NewsletterSection({ title, text, placeholder, button, note, action, label = 'Email address' }: { title: string; text: string; placeholder: string; button: string; note?: string; action?: string; label?: string }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12 md:items-end\">\n        <div className=\"md:col-span-6\">\n          <h2 className=\"type-heading text-balance\">{title}</h2>\n          <p className=\"type-body mt-4 max-w-[52ch] text-(--color-muted)\">{text}</p>\n        </div>\n        <form action={action} method={action ? 'post' : undefined} className=\"md:col-span-5 md:col-start-8\">\n          <div className=\"flex flex-col gap-3 sm:flex-row sm:items-end\">\n            <label className=\"type-utility flex-1 text-(--color-muted)\">{label}\n              <input required type=\"email\" name=\"email\" autoComplete=\"email\" placeholder={placeholder} className=\"type-body mt-2 block w-full rounded-(--radius-button) border border-(--color-border) bg-(--color-surface) px-4 py-3 text-(--color-text) placeholder:text-(--color-muted)\" />\n            </label>\n            <button type=\"submit\" className=\"type-body shrink-0 rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background)\">{button}</button>\n          </div>\n          {note && <p className=\"type-utility mt-3 text-(--color-muted)\">{note}</p>}\n        </form>\n      </div>\n    </section>\n  )\n}\n",
  "categories": "import type { ElementType } from 'react'\n// OpusKit section — Categories: tiles that show the range at a glance — a picture, a name and how many are inside.\nexport function CategoriesSection({ link: L = 'a', title, items }: { link?: ElementType; title: string; items: { name: string; href?: string; image?: string; alt?: string; count?: string }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className={`mt-10 grid grid-cols-2 gap-x-4 gap-y-8 md:gap-x-6 ${items.length % 3 === 0 ? 'md:grid-cols-3' : 'md:grid-cols-4'}`}>\n          {items.map((c) => {\n            const tile = (\n              <>\n                <div className=\"aspect-[4/5] overflow-hidden rounded-(--radius-media) bg-(--color-surface)\">\n                  {c.image && <img src={c.image} alt={c.alt ?? ''} loading=\"lazy\" className=\"size-full object-cover transition-transform duration-500 motion-safe:group-hover:scale-[1.03]\" />}\n                </div>\n                <div className=\"mt-4 flex items-baseline justify-between gap-3\">\n                  <h3 className=\"type-heading [font-size:clamp(1.1rem,1.6vw,1.4rem)] group-hover:underline group-hover:underline-offset-4\">{c.name}</h3>\n                  {c.count && <span className=\"type-utility shrink-0 text-(--color-muted)\">{c.count}</span>}\n                </div>\n              </>\n            )\n            return <li key={c.name}>{c.href ? <L href={c.href} className=\"group block\">{tile}</L> : tile}</li>\n          })}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "press": "// OpusKit section — Press: what outlets wrote, the outlet set as type (no borrowed logos), and awards in a quiet line.\nexport function PressSection({ title, quotes, awards }: { title: string; quotes: { outlet: string; quote: string }[]; awards?: string[] }) {\n  return (\n    <section className=\"px-5 py-20 md:px-10 md:py-28\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 grid border-l border-t border-(--color-border) md:grid-cols-3\">\n          {quotes.map((q) => (\n            <li key={q.outlet} className=\"border-b border-r border-(--color-border) p-6 md:p-8\">\n              <figure className=\"flex h-full flex-col justify-between gap-10\">\n                <blockquote className=\"type-body text-balance [font-size:clamp(1.05rem,1.4vw,1.25rem)]\">“{q.quote}”</blockquote>\n                <figcaption className=\"type-display [font-size:clamp(1.2rem,1.8vw,1.6rem)]\">{q.outlet}</figcaption>\n              </figure>\n            </li>\n          ))}\n        </ul>\n        {awards && awards.length > 0 && (\n          <ul aria-label=\"Awards\" className=\"type-utility mt-8 flex flex-wrap gap-x-8 gap-y-2 text-(--color-muted)\">\n            {awards.map((a) => <li key={a}>{a}</li>)}\n          </ul>\n        )}\n      </div>\n    </section>\n  )\n}\n",
  "cta-band": "import type { ElementType } from 'react'\n// OpusKit section — CTA band: a slim mid-page offer — one line and one action — that keeps the page going rather than ending it.\nexport function CtaBandSection({ link: L = 'a', text, action, note }: { link?: ElementType; text: string; action: { label: string; href: string }; note?: string }) {\n  return (\n    <section className=\"px-5 py-10 md:px-10 md:py-14\">\n      <div className=\"mx-auto flex max-w-[1440px] flex-col gap-6 rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) px-6 py-8 md:flex-row md:items-center md:justify-between md:px-10\">\n        <div>\n          <h2 className=\"type-heading text-balance [font-size:clamp(1.3rem,2.4vw,2rem)]\">{text}</h2>\n          {note && <p className=\"type-utility mt-2 text-(--color-muted)\">{note}</p>}\n        </div>\n        <L href={action.href} className=\"type-body shrink-0 self-start rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background) md:self-auto\">{action.label}</L>\n      </div>\n    </section>\n  )\n}\n",
  "trust": "// OpusKit section — Trust strip: 3–5 short promises (shipping, returns, trial, guarantee) in one quiet row.\nconst COLS: Record<number, string> = { 3: 'lg:grid-cols-3', 4: 'lg:grid-cols-4', 5: 'lg:grid-cols-5' }\n\nexport function TrustSection({ items }: { items: { title: string; text: string }[] }) {\n  return (\n    <section aria-label=\"Our promises\" className=\"px-5 py-12 md:px-10 md:py-16\">\n      <ul className={`mx-auto grid max-w-[1440px] gap-x-8 gap-y-6 border-y border-(--color-border) py-8 sm:grid-cols-2 ${COLS[items.length] ?? 'lg:grid-cols-4'}`}>\n        {items.map((t) => (\n          <li key={t.title}>\n            <span aria-hidden className=\"mb-3 block size-1.5 rounded-full bg-(--color-accent)\" />\n            <p className=\"type-heading [font-size:clamp(1rem,1.3vw,1.15rem)]\">{t.title}</p>\n            <p className=\"type-utility mt-1 text-(--color-muted)\">{t.text}</p>\n          </li>\n        ))}\n      </ul>\n    </section>\n  )\n}\n",
  "schedule": "// OpusKit section — Schedule: the programme day by day — time, what happens, a line of detail. Days sit side by side\n// on wide screens and stack on phones; no tabs, so everything stays readable and searchable.\nexport function ScheduleSection({ title, days }: { title: string; days: { label: string; items: { time: string; title: string; detail?: string }[] }[] }) {\n  return (\n    <section className=\"px-5 py-24 md:px-10 md:py-32\">\n      <div className=\"mx-auto max-w-[1440px]\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <div className={`mt-12 grid gap-12 md:gap-10 ${days.length > 1 ? 'md:grid-cols-2' : ''} ${days.length > 2 ? 'xl:grid-cols-3' : ''}`}>\n          {days.map((d) => (\n            <div key={d.label}>\n              <h3 className=\"type-utility border-b border-(--color-text) pb-3\">{d.label}</h3>\n              <ol className=\"divide-y divide-(--color-border)\">\n                {d.items.map((it) => (\n                  <li key={it.time + it.title} className=\"grid grid-cols-[5rem_1fr] gap-4 py-4\">\n                    <span className=\"type-body text-(--color-muted) tabular-nums\">{it.time}</span>\n                    <div>\n                      <p className=\"type-heading [font-size:clamp(1.05rem,1.4vw,1.25rem)]\">{it.title}</p>\n                      {it.detail && <p className=\"type-body mt-1 text-(--color-muted)\">{it.detail}</p>}\n                    </div>\n                  </li>\n                ))}\n              </ol>\n            </div>\n          ))}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "integrations": "// OpusKit section — Integrations: the tools it connects to, set as type (no borrowed logos), with an optional line.\nexport function IntegrationsSection({ title, text, tools }: { title: string; text?: string; tools: string[] }) {\n  return (\n    <section className=\"px-5 py-20 md:px-10 md:py-28\">\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-4\">\n          <h2 className=\"type-heading text-balance\">{title}</h2>\n          {text && <p className=\"type-body mt-4 max-w-[40ch] text-(--color-muted)\">{text}</p>}\n        </div>\n        <ul className=\"grid grid-cols-2 self-start border-l border-t border-(--color-border) sm:grid-cols-3 md:col-span-8\">\n          {tools.map((t) => (\n            <li key={t} className=\"type-body flex items-center gap-3 border-b border-r border-(--color-border) px-4 py-5 md:px-5 md:py-6\">\n              <span aria-hidden className=\"type-utility grid size-9 shrink-0 place-items-center rounded-(--radius-button) bg-(--color-surface)\">{t[0]}</span>{t}\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "footer": "// OpusKit section — Footer in four variants (the recipe's footer style):\n//   signature — a big signature logo, columns of links with a wavy underline on hover (pure CSS, no script), the legal line. Dark.\n//   wordmark  — links and contact in a row, then the brand name spanning the full width.\n//   contact   — one big invitation with the email/phone as large links, details beside it.\n//   line      — logo, a few links and © in one quiet line.\nimport type { ElementType, ReactNode } from 'react'\n\nexport type FooterColumn = { title: string; links: { label: string; href: string; current?: boolean }[] }\nexport type FooterVariant = 'signature' | 'wordmark' | 'contact' | 'line'\ntype Link = { label: string; href: string }\n\nconst wavy = 'underline decoration-wavy decoration-transparent decoration-[1.5px] underline-offset-[6px] transition-[text-decoration-color] duration-200 hover:decoration-(--color-chapter-2,var(--color-accent)) focus-visible:decoration-(--color-chapter-2,var(--color-accent)) aria-[current=page]:decoration-(--color-chapter-2,var(--color-accent))'\n\nexport function FooterSection({ link: L = 'a', variant = 'signature', logo, brand, columns, legal, copyright, invite = 'Let’s talk', contact = [], light = false }: {\n  link?: ElementType; variant?: FooterVariant; logo: ReactNode; /** The name as text — the wordmark variant sets it huge. */ brand?: string; columns: FooterColumn[]\n  legal?: Link[]; copyright: string; /** contact variant: the invitation and the ways to reach you. */ invite?: string; contact?: Link[]; light?: boolean\n}) {\n  const links = columns.flatMap((c) => c.links)\n  const item = (l: Link & { current?: boolean }) => <L key={l.href + l.label} href={l.href} aria-current={l.current ? 'page' : undefined} className={wavy}>{l.label}</L>\n  const bottom = (\n    <div className=\"type-utility mx-auto mt-16 flex max-w-[1440px] flex-wrap justify-between gap-4 border-t border-current/20 pt-6 [font-size:0.9rem] opacity-70\">\n      <span>{copyright}</span>\n      {legal && <span className=\"flex gap-6\">{legal.map(item)}</span>}\n    </div>\n  )\n  const ground = light || variant === 'line' ? 'bg-(--color-background) text-(--color-text)' : 'bg-(--color-text) text-(--color-background)'\n\n  if (variant === 'line') return (\n    <footer className={`px-5 py-8 md:px-10 ${ground}`}>\n      <div className=\"type-utility mx-auto flex max-w-[1440px] flex-col items-center gap-4 border-t border-current/20 pt-6 text-center md:flex-row md:justify-between md:text-left\">\n        <div>{logo}</div>\n        <nav aria-label=\"Footer\" className=\"flex flex-wrap justify-center gap-6\">{links.slice(0, 5).map(item)}</nav>\n        <span className=\"opacity-70 [font-size:0.9rem]\">{copyright}</span>\n      </div>\n    </footer>\n  )\n\n  if (variant === 'wordmark') return (\n    <footer className={`overflow-hidden px-5 pb-8 pt-16 md:px-10 ${ground}`}>\n      <nav aria-label=\"Footer\" className=\"type-utility mx-auto flex max-w-[1440px] flex-wrap gap-x-8 gap-y-3\">{links.map(item)}</nav>\n      <p aria-hidden className=\"type-display mx-auto mt-12 max-w-[1440px] whitespace-nowrap leading-[0.8] [font-size:clamp(4rem,17vw,16rem)]\">{brand ?? logo}</p>\n      {bottom}\n    </footer>\n  )\n\n  if (variant === 'contact') return (\n    <footer className={`px-5 pb-8 pt-20 md:px-10 ${ground}`}>\n      <div className=\"mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-8\">\n          <h2 className=\"type-display [font-size:clamp(2.6rem,6vw,5.5rem)]\">{invite}</h2>\n          <ul className=\"type-heading mt-8 space-y-2 [font-size:clamp(1.3rem,2.4vw,2rem)]\">{contact.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}</ul>\n        </div>\n        <div className=\"type-body space-y-6 opacity-90 md:col-span-4\">\n          {logo}\n          {columns.map((col) => (\n            <nav key={col.title} aria-label={col.title}>\n              <h3 className=\"type-utility opacity-70\">{col.title}</h3>\n              <ul className=\"mt-2 space-y-1\">{col.links.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}</ul>\n            </nav>\n          ))}\n        </div>\n      </div>\n      {bottom}\n    </footer>\n  )\n\n  return (\n    <footer className={`px-5 pb-8 pt-16 md:px-10 ${ground}`}>\n      <div className=\"mx-auto grid max-w-[1440px] gap-12 border-t border-current/20 pt-16 md:grid-cols-12\">\n        <div className=\"md:col-span-5\">{logo}</div>\n        {columns.map((col) => (\n          <nav key={col.title} aria-label={col.title} className=\"md:col-span-2\">\n            <h2 className=\"type-heading [font-size:1.15rem]\">{col.title}</h2>\n            <ul className=\"type-utility mt-4 space-y-2 opacity-90\">\n              {col.links.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}\n            </ul>\n          </nav>\n        ))}\n      </div>\n      {bottom}\n    </footer>\n  )\n}\n",
}

export const heroSource: Partial<Record<HeroId, string>> = {
  "orbit-stickers": "'use client'\n// OpusKit section — Sticker orbit hero: a two-voice headline with brand stickers and photos on an ellipse around it.\n// Scrolling turns the ring (each sticker travels around the headline) while the ring drifts up and away.\n// Reduced motion: the ring stays still. Tokens only; the loud and quiet halves use the display and heading families.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nexport type OrbitItem = { src: string; alt: string; size?: number; tilt?: number }\n\nfunction Orbiter({ item, i, n, turn }: { item: OrbitItem; i: number; n: number; turn: MotionValue<number> }) {\n  const angle = (deg: number) => ((i / n) * 360 + deg) * (Math.PI / 180)\n  const left = useTransform(turn, (d) => `${50 + Math.cos(angle(d)) * 46}%`)\n  const top = useTransform(turn, (d) => `${50 + Math.sin(angle(d)) * 43}%`)\n  return (\n    <motion.img src={item.src} alt={item.alt} draggable={false} className=\"absolute -translate-x-1/2 -translate-y-1/2 select-none object-contain\"\n      style={{ left, top, width: item.size ?? 120, rotate: item.tilt ?? 0 }}\n      initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring', stiffness: 260, damping: 18, delay: 0.2 + i * 0.05 }} />\n  )\n}\n\nexport function OrbitHeroSection({ eyebrow, loud, quiet, line, items }: { eyebrow?: string; loud: string; quiet: string; line?: string; items: OrbitItem[] }) {\n  const ref = useRef<HTMLElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end start'] })\n  const turn = useTransform(scrollYProgress, [0, 1], [0, reduce ? 0 : 140])\n  const lift = useTransform(scrollYProgress, [0, 1], ['0%', reduce ? '0%' : '-35%'])\n  return (\n    <section ref={ref} className=\"relative h-[100svh] min-h-[640px] overflow-hidden px-5 md:px-10\">\n      <motion.div aria-hidden={false} className=\"absolute inset-0\" style={{ y: lift }}>\n        {items.map((it, i) => <Orbiter key={it.src + i} item={it} i={i} n={items.length} turn={turn} />)}\n      </motion.div>\n      <div className=\"relative z-10 mx-auto grid h-full max-w-[1100px] place-content-center text-center\">\n        {eyebrow && <p className=\"type-utility\">{eyebrow}</p>}\n        <h1 className=\"type-display mt-3 flex flex-wrap items-baseline justify-center gap-x-[0.25em]\">\n          <span>{loud}</span>\n          <span className=\"font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\">{quiet}</span>\n        </h1>\n        {line && <p className=\"type-utility mx-auto mt-6 max-w-[34ch]\">{line}</p>}\n      </div>\n    </section>\n  )\n}\n",
}
